// 简体中文 for the instrument catalog (cultures/instruments/asia.js, second half), keyed by entry id.
Object.assign(I18N["zh-CN"].instruments, {
"kai": { sound: "低沉、粗粝的喉音,带泛音地低吼,在弹拨的鲁特琴伴奏下以长长的节奏诗行连续吟诵数小时。", acoustics: "人声:挤压式低位发声,室带(假声带)加入次谐音 → 喉腔与口腔塑造泛音。", materials: "人声。", usage: "以低沉的喉音承载叙事,有时带有泛音。", role: "史诗叙事的独唱声部。", players: "кайчы(kaichi)歌手,传统上为男性,属阿尔泰、哈卡斯和绍尔等民族。", skills: "低沉的吼式喉音、泛音润色、背诵长篇史诗。", scenes: "夜间聚会与仪式上的史诗吟诵。", repertoire: "阿尔泰英雄史诗,如《Маадай-Кара》(Maadai-Kara)。", origin: "阿尔泰及南西伯利亚突厥语民族的喉音史诗唱法,用于演述英雄故事;此处以它代表契丹邻近的草原喉唱。", history: "кайчы 歌手以低沉的喉音配合托布秀尔(topshuur)鲁特琴吟诵长篇史诗;与蒙古呼麦(khöömii)相关。", today: "仍活跃于阿尔泰和哈卡斯歌手之中。", uncertain: "本条目以阿尔泰史诗唱法代指契丹时代的草原歌唱,而后者并无直接证据。", techniques: [{ name: "кай(凯)", how: "用深沉沙哑的喉音吟诵阿尔泰史诗。" }, { name: "каргыра(卡尔吉拉)", how: "极低的吼式唱法,由假声带产生低八度的次谐音。" }, { name: "сыгыт(锡吉特)", how: "在紧绷的喉部持续低音之上吹出哨音般的泛音旋律。" }] },
"khonkh": { sound: "明亮、高亢、银铃般的响声,起音迅速,余音长而闪烁;连续摇动时,在诵经声上方形成稳定颤动的叮铃声。", acoustics: "内部自由的铃舌撞击青铜壁(激励方式:摇动)→ 铃体振动 → 直接向外辐射,没有单独的共鸣体。", materials: "带柄的铸青铜铃,柄顶常为金刚杵。", making: "以钟铜(铃青铜)用失蜡法或砂型铸造,再车削抛光,铃柄通常以半个金刚杵为顶;许多蒙古寺院的铃来自西藏、尼泊尔和中原的作坊。", usage: "手持摇动发声。", role: "仪式的信号与色彩,标示法事的段落与时刻,而不演奏旋律。", players: "举行仪式的佛教喇嘛,以及萨满。", skills: "与金刚杵和鼓相配合的仪式摇铃节奏。", scenes: "佛教诵经与法会、萨满仪式。", repertoire: "蒙古佛教的礼仪诵经(庙会法事)和查玛(cham)面具舞。", meaning: "在金刚乘佛教中,铃象征智慧与阴性原理,左手持铃,右手持金刚杵(方便);其声被说是宣示空性。", origin: "蒙古人的手铃,用于佛教仪式(藏语 dril-bu)和萨满。", history: "16世纪随藏传佛教传入,带金刚杵柄的铃成为蒙古寺院的核心法器。", today: "仍存在于蒙古国和内蒙古的佛教寺院,1990年代以来得到复兴。", techniques: [{ name: "摇铃", how: "摇动手铃,铃舌撞击发出明亮的响声。" }] },
"tsan": { sound: "明亮、轰鸣的金属声浪,敞击时余音悠长而渐涨;摩擦或闷击则发出嘶嘶声或短促干脆的咔声,滚奏加速可汇成轰响。", acoustics: "两片铜板相互撞击或摩擦(激励方式:撞击/摩擦)→ 青铜板振动 → 直接向外辐射。", materials: "锤打成型的青铜圆盘,配布带手柄。", making: "用青铜合金锤打成中央有凸起圆顶的圆盘,布条或皮带穿过圆顶系作手柄;许多是西藏或中原为蒙古寺院制作的。", usage: "相互撞击或摩擦。", role: "寺院乐队中与鼓一起担任节奏和结构上的断句。", players: "寺院仪式乐队中的喇嘛。", skills: "渐快的撞击节奏、闷击。", scenes: "寺院诵经、查玛舞。", repertoire: "佛教礼仪诵经和查玛面具舞。", origin: "蒙古佛教寺院的铙钹,源自藏传仪式铙钹。", history: "用来标示诵经和查玛面具舞的段落。", today: "仍存在于复兴的蒙古国和内蒙古寺院。", techniques: [{ name: "撞击", how: "两片钹相击而鸣。" }, { name: "闷击", how: "击后将两钹压紧,发出短促干脆的撞击声。" }] },
"kogerge": { sound: "深沉、轰鸣的沉重鼓声,音高低而共鸣,衰减迅速,响亮得足以传遍营地或战场。", range: "无固定音高或音高大致不定,低沉。", acoustics: "鼓槌敲击皮面(激励方式:敲击)→ 膜振动 → 封闭的釜形鼓腔加强低音。", materials: "铜制或木制鼓腔,蒙皮鼓面。", making: "以铜或雕凿的木头为鼓腔,绷上生皮鼓面,以皮绳系紧或钉牢。", usage: "以鼓槌敲击,常架在马或骆驼上。", role: "信号与号令:定下行军、推进与进攻。", players: "可汗和将领的军鼓手。", skills: "推进与进攻的信号节奏。", scenes: "战场、营地、可汗的宫廷典礼。", meaning: "战鼓体现统治者或将领的权威与精神(苏勒德,sülde);拥有大鼓标志着地位。", origin: "蒙古帝国的釜鼓,驮在马或骆驼上;突厥语 kövrüg / 蒙古语 kögürge。", finds: "13至14世纪的文献,如《蒙古秘史》和波斯编年史,记述了蒙古和突厥的战用釜鼓。", history: "大型釜鼓在蒙古军队中传达号令,是将领权威的象征。", today: "不再用于战争;重建的复制品出现在历史庆典和那达慕仪式上。", uncertain: "蒙古帝国釜鼓的确切形制与构造主要见于文字描述,没有实物传世。", techniques: [{ name: "鼓面击奏", how: "弯头鼓槌击打釜鼓,发出深沉的轰鸣。" }, { name: "滚奏", how: "快速连击,如滚滚雷声。" }] },
"sitar": { sound: "明亮、闪烁、带嗡嗡声的音色:平坦的“贾瓦里”(jawari)琴码使每次弹拨都带有丰富的西塔琴式嗡鸣,共鸣弦则如光晕般余响不绝。梅恩德(meend)拉弦如人声般在一个品位上滑过多个音,恰拉(jhala)则与持续音弦一起奏出快速、有节奏的闪烁声。", range: "约三个八度;主弦定为 Ma,即主音 Sa 的下四度,Sa 通常定在 C♯ 左右。", tuning: "主弦定为 Ma,其后是 Sa、Pa 和高音 Sa 的持续音弦(chikari);可动品和共鸣弦依所奏拉格的音调定。", acoustics: "金属拨片拨动钢弦(激励方式:拨弦)→ 琴弦在宽阔平坦的骨制琴码上振动并产生嗡鸣 → 葫芦与木面板共鸣,同时共鸣弦随之振动。", materials: "葫芦共鸣体、柚木琴颈、弧形金属品、约6至7根演奏弦和11至13根钢与青铜制共鸣弦、金属丝拨片 मिज़राब(mizrab)。", making: "由加尔各答、瓦拉纳西、德里和米拉吉的专门作坊,用干南瓜葫芦和吞木(tun)或柚木制成,配骨制或塑料配件;贾瓦里琴码需手工修整以获得嗡鸣。", usage: "斜置于膝上,食指戴金属丝拨片弹拨,左手在品位上拉弦。", role: "独奏旋律乐器,由塔布拉鼓和坦普拉琴伴奏。", players: "印度斯坦古典音乐家,历史上多出自世袭的家族流派(gharana)。", skills: "在一个品位上可拉出多达五个音的 मींड(meend)、加马克(gamak)、कृन्तन(krintan)击弦、恰拉(jhala)节奏扫弦。", scenes: "印度斯坦古典音乐会、莫卧儿和土邦宫廷、电影音乐。", repertoire: "以阿拉普(alap)、卓尔(jor)、恰拉和加特(gat)形式演奏拉格;知名演奏家包括拉维·香卡(Ravi Shankar)和维拉亚特·汗(Vilayat Khan)。", notation: "以口传教学,用音节式 bol 节奏型(da、ra、dir);另以书面的 sargam 和巴特坎德(Bhatkhande)记谱法辅助。", origin: "北印度的长颈有品鲁特琴,18世纪出现于莫卧儿及后莫卧儿宫廷,源自波斯塞塔尔(setār)型鲁特琴和印度维纳琴传统。", history: "由马西特·汗(Masit Khan)、拉扎·汗(Raza Khan)等宫廷乐师发展而成,增添了共鸣弦和弧形可动品;20世纪由拉维·香卡和维拉亚特·汗推向世界。", variants: "苏尔巴哈尔(surbahar)是更大的低音西塔琴;伊姆达德汗派(Imdadkhani,歌唱式)与迈哈尔(Maihar)家族流派风格不同。", today: "仍广泛流传,自1960年代起闻名世界。", techniques: [{ name: "梅恩德", how: "将琴弦横向拉过品位,使音高平滑地弯过数个音。" }, { name: "加马克", how: "音与音之间沉重的摆动,由反复偏拉琴弦产生。" }, { name: "克林坦", how: "左手勾弦与击弦发音,不用拨片。" }, { name: "恰拉", how: "快速的拨弦在旋律弦与 chikari 持续音弦之间交替,形成快速而响亮的脉动。" }, { name: "共鸣扫弦", how: "拨片扫过共鸣弦,发出闪烁的声浪。" }] },
"sarod": { sound: "深沉、共鸣丰厚、略带空洞感的音色,起音有力,无品金属指板带来滑动的、近乎人声的质感;长滑音在音与音之间平顺滑过,恰拉(jhala)扫弦则与持续音弦一同响亮回荡。", range: "约三个八度。", tuning: "演奏弦定为 Sa、Pa、Ma 和低音 Sa,配持续音弦(chikari);共鸣弦依拉格调定。", acoustics: "椰壳拨片拨动金属弦(激励方式:拨弦)→ 琴弦在羊皮面板上的琴码处振动 → 皮面与中空木身共鸣,共鸣弦增添余响。", materials: "蒙羊皮的木质琴身、抛光的金属指板、金属制演奏弦与共鸣弦、椰壳拨片。", making: "以整块柚木雕成,配羊皮面板、抛光钢指板和琴颈端的金属共鸣体,由主要在加尔各答的专门乐器匠人制作。", usage: "横置于膝上,用拨片拨弦,同时指甲在金属指板上滑动。", role: "独奏旋律乐器,与塔布拉鼓和坦普拉琴合奏。", players: "印度斯坦古典音乐家,尤其是迈哈尔(Maihar)和班加什(Bangash,瓜廖尔—班加什)传承脉络。", skills: "在无品指板上的长滑音“梅恩德”(meend)、加马克(gamak)、恰拉扫弦、快速塔恩(tan)。", scenes: "印度斯坦古典音乐会,尤其在孟加拉及迈哈尔传统中。", repertoire: "以阿拉普、卓尔、恰拉和加特演奏拉格;因阿劳丁·汗(Allauddin Khan)、阿里·阿克巴·汗(Ali Akbar Khan)和阿姆贾德·阿里·汗(Amjad Ali Khan)而闻名。", notation: "以 bol 口传教学,以 sargam 或巴特坎德记谱法辅助。", origin: "北印度的无品鲁特琴,19世纪由定居印度的阿富汗乐师家族从阿富汗热瓦普(rubab)发展而来。", history: "班加什家族等乐师,以及后来迈哈尔家族流派(与孟加拉关系密切)的阿劳丁·汗和阿里·阿克巴·汗,使它成为重要的古典乐器。", today: "仍活跃于印度斯坦古典音乐。", techniques: [{ name: "滑音", how: "左手指甲沿无品金属指板滑动,在音与音之间平顺滑过。" }, { name: "加马克", how: "音与音之间沉重而快速的摆动。" }, { name: "恰拉", how: "在旋律弦与持续音弦上快速交替拨奏。" }, { name: "共鸣扫弦", how: "拨片扫过共鸣弦,发出闪烁的声浪。" }] },
"rudra-veena": { sound: "深沉、幽暗、沉思般的音色,延音很长;大葫芦带来柔和圆润的低音,缓慢的梅恩德(meend)拉弦和安多兰(andolan)摆动使音符如人声般摇曳。", range: "低音区,约四个八度,kharaj 低音弦比主音低一个八度或更多。", tuning: "演奏弦按 Ma、Sa、Pa、低音 Sa 的格式定弦,配持续音弦(chikari);高音品用蜡固定,旋律依所奏拉格而定。", acoustics: "金属丝拨片拨动钢弦与青铜弦(激励方式:拨弦)→ 琴弦在平坦琴码上嗡鸣 → 琴杆振动,两只葫芦共鸣。", materials: "一根长木管或竹管、两只大葫芦、蜡固定的高音木品、钢弦与青铜弦。", making: "大木管或竹管上装两只大葫芦,由少数专门工匠手工制作;品用蜡固定,便于调整。", usage: "扛在肩上或斜置于膝上,用金属丝拨片弹拨,左手在品位上拉弦。", role: "在缓慢沉思的德鲁帕德(dhrupad)风格中独奏旋律,由帕克瓦吉鼓(pakhawaj)伴奏。", players: "塞尼亚(Seniya)和达加尔(Dagar)传承的德鲁帕德音乐家;历史上为宫廷乐师。", skills: "带深沉梅恩德与加马克的缓慢阿拉普、低音 kharaj 共鸣、安多兰摆动。", scenes: "德鲁帕德音乐会、莫卧儿与拉杰普特宫廷、寺庙音乐。", repertoire: "德鲁帕德的阿拉普与乐曲;阿萨德·阿里·汗(Asad Ali Khan)和齐亚·莫希丁·达加尔(Zia Mohiuddin Dagar)是20世纪的大师。", notation: "口传教学,以 sargam 辅助。", meaning: "以鲁德拉(Rudra,即湿婆)命名,被视为神圣乐器,据说由湿婆受帕尔瓦蒂启发而创造。", origin: "北印度带两只葫芦共鸣体的棍形齐特琴,称为“鲁德拉(湿婆)的维纳”,是德鲁帕德传统的古老乐器。", history: "在莫卧儿宫廷备受推崇(坦森的后裔是维纳琴演奏者),20世纪衰落,由少数德鲁帕德大师延续;低音 kharaj 弦赋予它深沉的持续音。", variants: "齐亚·莫希丁·达加尔的达加尔式鲁德拉维纳,葫芦更大、琴管更宽,音色更深沉。", today: "濒危;由少数演奏者维系。", techniques: [{ name: "梅恩德", how: "在高音品上深深拉弦,使音高弯过数个音,是德鲁帕德演奏的标志。" }, { name: "加马克", how: "缓慢而沉重的音高摆动。" }, { name: "恰拉", how: "在旋律弦与 chikari 弦上快速拨奏。" }] },
"veena": { sound: "温暖、丰厚、柔和的音色,低音共鸣饱满;左手在品位上拉弦弯音,奏出独特的摇摆加马卡(gamaka),塔拉弦(tala)则增添轻快的节奏响声。", range: "约三个半八度。", tuning: "四根演奏弦定为 Sa、Pa、Sa、Pa(较低八度),另有三根持续音弦(Sa、Pa、Sa);24个固定品给出每八度十二个半音,卡纳提克拉格以加马卡在其上演奏。", acoustics: "指甲拨动金属弦(激励方式:拨弦)→ 琴弦在琴码上振动 → 大型菠萝蜜木琴身与副葫芦共鸣。", materials: "菠萝蜜木琴身与琴颈、琴颈末端下的葫芦、蜡固定的24个黄铜品、四根演奏弦与三根持续音弦、龙头琴首。", making: "以菠萝蜜木雕成,传统上以坦贾武尔(Thanjavur)所产最佳,工匠在那里制作琴身(有时整把乐器取自一根原木,称 ekanda);品嵌在蜡与木炭的底座中。", usage: "水平横置于膝上,右手指甲弹拨,左手在品位上拉弦。", role: "独奏旋律,也为人声伴奏。", players: "卡纳提克音乐家,历史上既有宫廷乐师也有家庭乐师,许多是女性。", skills: "拉弦产生的加马卡摆动、滑音、用小指击奏塔拉弦。", scenes: "卡纳提克音乐会、寺庙音乐、宗教与家庭音乐。", repertoire: "提亚加拉贾(Tyagaraja)、穆图斯瓦米·迪克希塔尔(Muthuswami Dikshitar)和夏马·夏斯特里(Syama Sastri)的卡纳提克克里提(kriti)与瓦尔纳姆(varnam);迪克希塔尔本人即演奏维纳琴。", notation: "带塔拉(tala)标记的卡纳提克 sargam(sa ri ga ma)记谱。", meaning: "知识与音乐女神萨拉斯瓦蒂的乐器;受到崇敬,并在萨拉斯瓦蒂节(Saraswati Puja)上被供奉。", origin: "以女神萨拉斯瓦蒂命名的南印度有品鲁特琴,17世纪在坦贾武尔宫廷由更古老的泰米尔和梵语 vīṇā 传统发展而来。", history: "坦贾武尔的拉古那塔·纳亚克(Raghunatha Nayak)被认为创制了24品的形制;它成为典型的卡纳提克乐器,也是萨拉斯瓦蒂圣像中的乐器。", variants: "坦贾武尔、迈索尔和安得拉(博比利,Bobbili)风格在琴身与装饰上各有不同。", today: "仍流传;坦贾武尔维纳琴获得了地理标志认证。", techniques: [{ name: "加马卡(கமகம்)", how: "在品位上拉弦,形成卡纳提克音乐中摆动的装饰音。" }, { name: "贾鲁(ஜாரு)", how: "手指沿品位滑动,在音与音之间滑过。" }, { name: "塔拉弦", how: "小指拨击侧面的持续音弦以保持节拍。" }] },
"kinnari-veena": { sound: "轻柔、带轻微嗡嗡声的拨弦音色,持续音弦在旋律之下回响。", acoustics: "手指拨动金属丝弦(激励方式:拨弦)→ 琴弦在高品上振动 → 琴杆及其葫芦共鸣。", materials: "竹制或木制琴杆、两三只葫芦、骨制或金属制的品、金属丝弦。", making: "由演奏者自己的群体用竹、葫芦和金属丝制作;品多为骨或黄铜,以蜡固定。", usage: "抱于身前弹拨,左手按品。", role: "带持续音的旋律,为叙事演唱伴奏。", players: "德干地区的行吟艺人群体(如泰伦加纳的达卡利 Dakkali 和金纳拉 Kinnera 演奏者)。", skills: "配合持续音弦的旋律拨奏。", scenes: "中世纪宫廷、德干行吟叙事。", repertoire: "叙事歌谣与种姓谱系。", origin: "中世纪印度带数只葫芦共鸣体的棍形齐特琴,以天界乐神紧那罗(kinnara)命名;13世纪的《乐海》(Sangita Ratnakara)中已有描述。", finds: "13世纪沙兰伽提婆(Sharngadeva)的《乐海》中有记述;中世纪寺庙雕刻中出现带葫芦的棍形齐特琴。", history: "曾是宫廷乐器,今作为民间乐器留存于德干的行吟艺人群体中。", variants: "民间形制的葫芦数与品数各不相同。", today: "濒危;泰伦加纳的12品金纳拉琴(kinnera)经大师达尔夏南·莫古拉伊亚(Darshanam Mogulaiah)而得以复兴。", techniques: [{ name: "梅恩德", how: "在高品上拉弦使音高弯曲。" }] },
"tanpura": { sound: "连绵不断、嗡嗡作响、泛音丰富的持续音:贾瓦里(jawari)琴码和丝线使每根弦绽放成一团闪烁的泛音云,仿佛自己在歌唱。起音柔和,余音相互重叠成无缝的声浪。", range: "固定的主音持续音:通常为 Pa(或 Ma 或 Ni)、Sa、Sa 和低音 Sa,依歌者的主音定高。", tuning: "依独奏者的主音 Sa 定弦;第一根弦视拉格定为 Pa、Ma 或 Ni,并用小珠和 jiva 丝线微调以获得最佳嗡鸣。", acoustics: "手指拨动空弦(激励方式:拨弦)→ 琴弦擦过宽阔的弧形琴码,棉线(jiva)决定擦弦点 → 葫芦或木制琴身与面板共鸣。", materials: "葫芦或木制琴身、长而中空的琴颈、四五根钢弦与青铜弦、带棉线的骨制琴码。", making: "与西塔琴出自同样的作坊,位于米拉吉、加尔各答和瓦拉纳西;米拉吉尤以坦普拉琴闻名,以干葫芦和吞木(tun)制成。", usage: "竖持于膝上或地上;琴弦按缓慢、连续的循环不停地拨弹。", role: "持续音:每场拉格演奏不变的音调根基。", players: "学生和伴奏乐师,常为歌者的弟子;歌者也自己弹奏。", skills: "调整贾瓦里丝线以得到嗡鸣声、均匀循环的拨弦。", scenes: "各类古典音乐会、宗教歌唱、拉贾斯坦民间音乐与巴赞(bhajan)。", repertoire: "印度斯坦与卡纳提克古典音乐中处处可闻。", origin: "印度古典音乐的无品持续音鲁特琴,南印度称 tambura;“tandura”则是拉贾斯坦的民间持续音鲁特琴。", history: "其弧形琴码“贾瓦里”配以丝线“jiva”,产生嗡鸣而泛音丰富的持续音;至少自莫卧儿时期起就为歌者和器乐演奏者伴奏。", variants: "有男式(较大)与女式(较小)之分,南方有扁身的坦焦尔坦布拉(tanjore tambura),拉贾斯坦有民间的 tandura,今日还有电子坦普拉琴。", today: "仍流传;电子坦普拉琴盒和应用程序与之并用,十分普遍。", techniques: [{ name: "贾瓦里持续音(जवारी)", how: "弧形琴码上的丝线使每根拨动的弦嗡鸣并绽放泛音。" }, { name: "持续音循环", how: "琴弦依次拨动,缓慢而不间断地循环。" }] },
"swarmandal": { sound: "明亮、悠扬、竖琴般的滑奏,如拉格音符的光晕悬在歌声周围,在歌者乐句下起音柔和。", tuning: "每根弦定为所唱拉格的一个音,因此一次扫弦只奏出该拉格的音阶。", acoustics: "手指或拨片扫弦(激励方式:拨弦)→ 金属弦振动 → 木箱共鸣。", materials: "木箱上装许多按拉格定音的金属弦。", making: "长方形木箱,配调音弦轴和钢弦,由北印度的乐器作坊制作。", usage: "置于膝上或抱在胸前,用手指扫弦。", role: "为人声增添色彩与支撑;不是旋律乐器。", players: "印度斯坦声乐家,边唱边自己弹奏。", skills: "与拉格相配的滑奏扫弦、依拉格音阶调弦。", scenes: "印度斯坦声乐音乐会、轻古典歌曲。", repertoire: "卡亚尔(khayal)与轻古典演唱;巴德·古拉姆·阿里·汗(Bade Ghulam Ali Khan)以使用它闻名。", origin: "北印度的箱式齐特琴,与波斯卡农琴(qanun)相关。", history: "印度斯坦歌手采用它为自己的歌声伴奏并润色,扫弦成拉格音符的光晕。", today: "仍活跃于印度斯坦歌手之中。", techniques: [{ name: "滑奏", how: "手指或拨片扫过琴弦,在歌声后形成闪烁的声浪。" }] },
"santoor": { sound: "清脆、明亮、闪烁的音色,如涟漪流水:每次槌击起音鲜明、余音响亮,快速滚奏汇成闪烁而持续的声云。", range: "约三个八度。", tuning: "演奏前将各组弦按拉格的音定好;琴码把琴弦分成几段,给出不同的八度。", acoustics: "轻巧的琴槌敲击成组钢弦(激励方式:击弦)→ 琴弦在可动琴码上振动 → 中空木箱共鸣。", materials: "梯形核桃木箱,约100根钢弦分组架在可动琴码上,配轻巧的弧形核桃木琴槌。", making: "在克什米尔和北印度以核桃木或其他硬木制成,配钢弦和手工雕成的核桃木琴槌。", usage: "置于膝上,用两支轻槌敲击。", role: "旋律,既可独奏,也用于苏菲亚纳(sufiana)合奏。", players: "克什米尔的苏菲音乐家,后来也有印度斯坦古典独奏家。", skills: "滚奏颤音、快速跑句、用闷音使音更清晰。", scenes: "克什米尔苏菲聚会、古典音乐与电影音乐。", repertoire: "克什米尔的苏菲亚纳歌词(sufiana kalam);希夫库马尔·夏尔马(Shivkumar Sharma)的古典独奏会,以及 Shiv–Hari 的电影音乐。", origin: "克什米尔的击弦扬琴,与波斯桑图尔(santur)相关。", history: "长期用于克什米尔苏菲音乐“苏菲亚纳歌词”,20世纪由希夫库马尔·夏尔马改造用于印度斯坦古典音乐。", variants: "克什米尔的苏菲亚纳桑图尔,以及希夫库马尔·夏尔马改良的更大的古典桑图尔。", today: "仍流传,既在克什米尔,也在古典舞台上。", techniques: [{ name: "击音", how: "轻巧的核桃木琴槌敲击琴弦,发出明亮响亮的音。" }, { name: "颤音", how: "琴槌快速交替敲击以持续一个音。" }, { name: "滑奏", how: "琴槌扫过琴弦,形成倾泻而下的音流。" }, { name: "止音", how: "用手或琴槌按住琴弦,使音变短。" }] },
"sarangi": { sound: "深沉、哀婉、带鼻音的音色,常被比作人声,数十根共鸣弦营造出一片共鸣云;梅恩德(meend)滑音在音与音之间连续滑行,快速的加马克(gamak)颤动增添张力。", range: "约三个八度。", tuning: "三根肠弦演奏弦定为 Sa、Pa(或 Ma)和低音 Sa;共鸣弦按半音阶并依拉格定音。", acoustics: "马尾弓激励肠弦(激励方式:拉弦)→ 以指甲根部按弦的琴弦在羊皮面板上的琴码处振动 → 中空的吞木(tun)琴身共鸣,众多共鸣弦随之回响。", materials: "蒙羊皮的吞木空心琴身、三根肠制演奏弦和多达36根共鸣弦。", making: "由莫拉达巴德、德里和勒克瑙等地的专门工匠,以整块吞木(红柏)雕成并蒙以羊皮。", usage: "竖持于膝上,用弓拉奏,以指甲根部侧压琴弦按音。", role: "紧随歌者的旋律伴奏,也作独奏旋律。", players: "世袭的乐师家族,历史上为名妓歌者伴奏;后来成为音乐会独奏家。", skills: "如人声般连绵的梅恩德滑音、加马克、紧随歌者。", scenes: "印度斯坦声乐伴奏、名妓沙龙、卡塔克舞、民间音乐。", repertoire: "为卡亚尔(khayal)、图姆里(thumri)和加扎尔(ghazal)伴奏;拉姆·纳拉扬(Ram Narayan)和苏丹·汗(Sultan Khan)的拉格独奏会。", notation: "口传教学,以 sargam 辅助。", origin: "北印度的短颈弓弦鲁特琴,源自拉贾斯坦和旁遮普的民间提琴。", history: "18至19世纪成为印度斯坦声乐的主要伴奏乐器,后来成为独奏乐器(拉姆·纳拉扬);据说拥有“百种色彩”。", variants: "古典萨朗吉,以及拉贾斯坦和旁遮普的几种民间萨朗吉(信德、古贾拉坦、达尼、乔吉亚)。", today: "仍流传,但年轻演奏者很少。", techniques: [{ name: "指甲按弦", how: "以指甲根部侧压琴弦按音,得到人声般的音色。" }, { name: "梅恩德(मींड)", how: "指甲沿琴弦滑动,如人声般在音与音之间滑行。" }, { name: "加马克(गमक)", how: "音高宽幅而沉重的摆动。" }] },
"sindhi-sarangi": { sound: "带簧片感的鼻音弓弦音色,共鸣弦发出悠长的持续音;弓上的铃有时增添轻快的叮当节奏。", tuning: "肠制演奏弦定为主音及其五度或四度,共鸣弦依民间调式定音。", acoustics: "弓激励肠弦(激励方式:拉弦)→ 琴弦在羊皮面板上的琴码处振动 → 中空的雕刻琴身与共鸣弦一起共鸣。", materials: "雕刻的木身配蒙皮面板、肠弦与钢弦,有时在弓上附铃。", making: "以整块木头雕成,配羊皮面板,常由乐师自己群体或当地木匠制作。", usage: "竖持拉奏,用手指侧面按弦。", role: "为歌者提供旋律与持续音。", players: "拉贾斯坦西部和信德的朗加(Langa)乐师。", skills: "带装饰的民间旋律,配以持续音共鸣弦。", scenes: "塔尔沙漠地区的婚礼、诞生仪式和赞助人聚会。", repertoire: "为赞助人演唱的民歌、苏菲诗歌和塔尔沙漠的婚礼歌。", origin: "拉贾斯坦西部和信德的朗加与曼加尼亚尔(Manganiyar)乐师的民间萨朗吉。", history: "世袭乐师为其赞助人的仪式演奏;设肠制演奏弦和众多共鸣弦。", today: "仍活跃于朗加家族之中,也登上世界音乐舞台。", techniques: [{ name: "指甲按弦", how: "用指甲从侧面按弦,发出带鼻音而悠扬的音色。" }, { name: "滑音", how: "指甲在音与音之间滑动。" }] },
"esraj": { sound: "柔和、甜美、如歌唱般的弓弦音色,比萨朗吉更温婉,带有共鸣弦的余响;沿品位滑动产生平顺的、如人声般的滑音。", range: "约三个八度。", tuning: "四根主弦的定法与西塔琴相同(Ma、Sa、Pa、Sa),共鸣弦依拉格定音;可动品确定音阶。", acoustics: "弓激励主弦(激励方式:拉弦)→ 琴弦在羊皮面板上的琴码处振动 → 木制琴身共鸣,共鸣弦增添色彩。", materials: "蒙羊皮面板的木制琴身、带金属品的西塔琴式琴颈、四根演奏弦与共鸣弦。", making: "由加尔各答和北印度的乐器作坊以木头和羊皮制成,配金属品和金属弦。", usage: "竖持拉奏,左手在品位上滑动。", role: "旋律,为歌唱伴奏。", players: "孟加拉乐师、圣蒂尼克坦(Santiniketan)的学生、锡克教基尔坦(kirtan)乐师。", skills: "沿品位的梅恩德滑音、持续的歌唱性音色。", scenes: "泰戈尔歌曲(Rabindrasangeet)、宗教基尔坦、孟加拉轻音乐。", repertoire: "泰戈尔歌曲(Rabindrasangeet)和锡克教圣歌(gurbani)基尔坦。", origin: "孟加拉和印度东部的有品弓弦鲁特琴,是迪尔鲁巴(dilruba)较轻巧的近亲,约有两个世纪的历史。", history: "拉宾德拉纳特·泰戈尔(Rabindranath Tagore)使它成为圣蒂尼克坦音乐的核心;它也为锡克教基尔坦伴奏。", variants: "旁遮普和北印度较大的迪尔鲁巴。", today: "仍流传但已不常见;在锡克教基尔坦中得到复兴。", techniques: [{ name: "梅恩德(মীড়)", how: "手指沿琴弦在品位上滑动,在音与音之间滑行。" }, { name: "揉弦", how: "摇动手指使拉奏的音微微颤动。" }] },
"sarinda": { sound: "粗粝、带鼻音、质朴的弓弦音色,弓法带来强烈的节奏感,有时弓上挂有叮当作响的铃。", acoustics: "弓激励三根肠弦(激励方式:拉弦)→ 琴弦在下部蒙皮部分的琴码上振动 → 束腰的、部分敞开的木制琴身共鸣。", materials: "部分蒙皮的整块木头、肠弦、带铃的弓。", making: "以整块木头雕成,下部蒙皮,常由演奏者或当地工匠制作。", usage: "竖持拉奏,用指甲按弦。", role: "为歌唱与舞蹈提供旋律与节奏。", players: "北印度、巴基斯坦、尼泊尔和阿富汗的民间乐师、流浪艺人和部落群体。", skills: "弓法中推动性的民间节奏、装饰音。", scenes: "民歌与民间舞蹈、行吟叙事。", repertoire: "民歌、舞曲和行吟叙事。", origin: "带束腰、部分敞开琴身的弓弦民间提琴,见于拉贾斯坦、旁遮普、信德以及更北的阿富汗。", history: "由流浪的民间乐师以及包尔(Baul)和部落歌者演奏,设三根弦,无品。", variants: "阿富汗、旁遮普、拉贾斯坦的形制,以及阿萨姆和孟加拉的部落形制,在大小和弦数上各不相同。", today: "作为民间乐器正在衰落。", techniques: [{ name: "滑音", how: "指甲沿琴弦在音与音之间滑动。" }] },
"kamaicha": { sound: "深沉、轰鸣、共鸣丰厚的弓弦音色:大型蒙皮圆腔和众多共鸣弦在低吼般的旋律之下形成嗡鸣回响的持续音。", tuning: "肠制演奏弦定为主音及五度或四度,钢制共鸣弦依民间调式定音。", acoustics: "马尾弓激励肠弦(激励方式:拉弦)→ 琴弦在大圆腔羊皮上的琴码处振动 → 腔体与共鸣弦共鸣。", materials: "芒果木琴身、羊皮、肠制演奏弦与钢制共鸣弦、马尾弓。", making: "以整块芒果木或印度黄檀(sheesham)雕成,由巴尔梅尔和杰伊瑟尔梅尔地区的工匠为曼加尼亚尔人制作。", usage: "竖持拉奏,用指尖从侧面按弦。", role: "为歌者提供旋律伴奏与持续音。", players: "塔尔沙漠的曼加尼亚尔世袭乐师。", skills: "众多共鸣弦产生的共鸣持续音、人声之下的装饰性旋律。", scenes: "婚礼与诞生仪式、赞助人的庭院、沙漠节庆。", repertoire: "曼加尼亚尔为赞助人演唱的歌曲、婚礼歌和苏菲诗歌。", origin: "带大型圆形蒙皮腔体的弓弦鲁特琴,由塔尔沙漠的曼加尼亚尔乐师演奏。", history: "该地区最古老的弓弦乐器之一,在人生礼仪上为赞助人的歌曲伴奏。", today: "濒危:仅存少数大师和制作者;在节庆舞台上得到复兴。", techniques: [{ name: "铃弓", how: "带小铃的弓拉过肠弦,增添叮当声。" }, { name: "滑音", how: "手指在音与音之间滑动。" }] },
"ravanahatha": { sound: "纤细、沙哑、带鼻音的弓弦音色,伴有嗡嗡的持续音,弓上的铃随每一弓而叮当作响。", acoustics: "弓激励马尾或钢制的主弦(激励方式:拉弦)→ 琴弦在蒙皮琴壳上的琴码处振动 → 椰壳琴身共鸣,并有持续音弦与共鸣弦。", materials: "蒙皮的椰壳或葫芦琴身、竹制琴颈、马尾弦与钢弦、带铃的弓。", making: "通常由演奏者本人或村中工匠以半个椰壳、皮、竹和马尾制成。", usage: "竖持拉奏,弓上的铃打着节奏。", role: "为行吟者自己的演唱提供旋律与持续音。", players: "拉贾斯坦的博帕(Bhopa)祭司兼行吟者,常有一位女伴举灯照向画卷。", skills: "带铃的运弓、持续音弦、长篇叙事伴奏。", scenes: "帕布吉画卷(Pabuji ki phad)史诗演出、乡村集市。", repertoire: "对着画卷演唱的帕布吉史诗(Pabuji ki phad)。", meaning: "传说楞伽之王、湿婆信徒罗波那(Ravana)创造了它;其名意为“罗波那之手”。", origin: "拉贾斯坦的简易弓弦提琴,椰壳琴身,传说与《罗摩衍那》中的罗波那有关。", history: "博帕行吟者在彩绘画卷“phad”前演唱帕布吉史诗时演奏它。", variants: "南亚各地(包括斯里兰卡)都有类似的简易提琴。", today: "作为史诗伴奏已濒危;在拉贾斯坦也卖给游客。", uncertain: "称其为世界上最古老的弓弦乐器,依据的是传说,而非有年代可考的证据。", techniques: [{ name: "铃弓", how: "弓上带铃,每拉一弓即叮当作响。" }, { name: "滑音", how: "手指沿琴弦在音与音之间滑动。" }] },
"ektara": { sound: "弹跳般的、富有弹性的单音持续音,捏压竹制琴颈时音高上下滑荡,在歌声之下发出“嘣”般的弹性声响。", range: "单音,上下弯曲约数个半音。", acoustics: "手指拨动一根弦(激励方式:拨弦)→ 固定在皮膜上的琴弦振动 → 葫芦或鼓形琴身共鸣;捏压劈开的竹子可改变张力。", materials: "蒙皮的葫芦或木制琴身、劈开的竹制琴颈、一根钢弦。", making: "由演奏者或村中工匠以葫芦或挖空的木头、羊皮、劈开的竹子和一根金属丝制成。", usage: "单手持握,食指拨弦,捏压竹子以弯音。", role: "为歌者提供持续音与节奏。", players: "包尔(Baul)行吟者及其他流浪的宗教歌者。", skills: "节奏性拨弦与捏压弯音。", scenes: "包尔与宗教歌唱、乡村集市。", repertoire: "包尔歌曲,包括拉隆·法基尔(Lalon Fakir)的作品。", meaning: "对包尔人而言,它的单弦象征合一,以及歌者对“心中之人”(moner manush)的虔信。", origin: "孟加拉和北印度的单弦持续音乐器,供流浪歌者使用。", history: "孟加拉的包尔行吟者以之伴歌伴舞;按压劈开的竹制琴颈可弯曲音高。", variants: "北印度的 ektara 是带葫芦的拨弦长颈持续音鲁特琴;孟加拉形制(gopiyantra)则有劈开的竹制琴颈。", today: "仍流传;包尔歌曲于2008年被联合国教科文组织列入名录。", techniques: [{ name: "捏压琴颈", how: "捏压劈开的竹制琴颈改变琴弦张力,如人声般弯曲音高。" }, { name: "节奏拨弦", how: "食指以稳定的脉动拨动单根弦。" }] },
"dotara": { sound: "明亮、弹跳、金属质感的拨弦音色,快速如涟漪的跑句和滑音,如班卓琴般穿透歌声。", acoustics: "拨片拨动金属弦(激励方式:拨弦)→ 琴弦在羊皮面板上的琴码处振动 → 雕刻的木身共鸣。", materials: "印楝木或菠萝蜜木雕刻的蒙皮琴身、无品琴颈、金属弦。", making: "以整块印楝木或菠萝蜜木雕成,配羊皮面板,常由当地工匠制作;琴首常雕成孔雀或天鹅。", usage: "斜抱于身前,用拨片弹拨。", role: "为歌唱提供旋律与伴奏。", players: "孟加拉和阿萨姆的包尔(Baul)与民间歌者。", skills: "带滑音的快速拨片旋律。", scenes: "包尔与民歌、乡村节庆。", repertoire: "包尔歌曲和北孟加拉的巴瓦亚(Bhawaiya)歌曲。", origin: "孟加拉和阿萨姆的无品拨弦鲁特琴,出自包尔与民间传统。", history: "为包尔和巴瓦亚歌曲伴奏;虽名为“两根弦”,却常有四根。", variants: "孟加拉的 dotara 有四根弦;北孟加拉和阿萨姆的巴瓦亚 dotara 是两弦或四弦的变体。", today: "仍活跃于孟加拉民间音乐。", techniques: [{ name: "拨弦", how: "拨片拨动琴弦,发出明亮的弹拨声。" }, { name: "滑音", how: "手指沿无品琴颈滑动。" }] },
"khamak": { sound: "弹跳般、橡胶般的“说话式”拨弦声,拉动琴弦时音高起伏,产生有节奏的、近乎说话的跳动感。", acoustics: "手指拨动一根弦(激励方式:拨弦)→ 固定于鼓皮的琴弦带动皮膜振动 → 小鼓壳共鸣;拉动手柄可改变音高。", materials: "蒙皮的小型木制或葫芦鼓、肠弦或钢弦、一个手柄。", making: "由演奏者或村中工匠以小木鼓壳、皮和肠弦或金属丝制成。", usage: "夹在腋下;一手拉弦,一手拨弦。", role: "带弯音效果的节奏伴奏。", players: "包尔(Baul)行吟者。", skills: "弯音的“说话式”节奏。", scenes: "包尔歌舞、乡村集市。", repertoire: "包尔歌曲与舞蹈。", origin: "孟加拉包尔行吟者的拨弦鼓:一根弦从鼓皮穿过小鼓,连到一个手柄。", history: "左手拉动琴弦改变张力,从而改变音高,同时右手拨弦,发出说话般的声音。", today: "仍活跃于包尔人之中。", techniques: [{ name: "拉拨", how: "绷紧琴弦拨奏,同时改变张力,得到跳跃的弯音。" }] },
"gottuvadhyam": { sound: "平滑、温暖、滑动的拨弦音色,延音很长:滑筒产生连续的、如人声般的滑音和加马卡(gamaka),共鸣弦增添余响。", range: "约三个八度。", tuning: "演奏弦的定法与维纳琴相同,持续音弦与共鸣弦依主音和拉格定音。", acoustics: "手指拨动金属弦(激励方式:拨弦)→ 以滑动的圆筒按弦的琴弦在琴码上振动 → 菠萝蜜木琴身共鸣,并有共鸣弦。", materials: "与维纳琴相同的菠萝蜜木琴身、无品琴颈、演奏弦、持续音弦与共鸣弦、木制或特氟龙圆筒滑具。", making: "由南印度工匠按维纳琴的做法制作,琴颈无品。", usage: "平放;右手指拨弦,左手在弦上滑动圆筒。", role: "卡纳提克音乐中的独奏旋律。", players: "少数卡纳提克家族和独奏家;N. 拉维基兰(N. Ravikiran)是当今的主要演奏者。", skills: "为加马卡而作的连续滑音、如人声的旋律。", scenes: "卡纳提克音乐会。", repertoire: "卡纳提克克里提(kriti)与拉格阿拉帕纳(alapana)。", origin: "南印度的无品卡纳提克鲁特琴,又称 chitravina,用滑具演奏。", history: "20世纪由萨卡拉马·拉奥(Sakharama Rao)和纳拉扬·艾扬格(Narayan Iyengar)复兴并推广,与维纳琴相关但无品。", variants: "拉维基兰的“navachitravina”是现代较小的版本。", today: "罕见但仍流传。", techniques: [{ name: "滑音", how: "圆筒滑具沿琴弦移动,产生滑行的加马卡。" }, { name: "共鸣回响", how: "共鸣弦在旋律之下回响。" }] },
"yazh": { sound: "可能是柔和的、竖琴般的拨弦音色,衰减轻缓,比后来的鲁特琴更安静。", acoustics: "手指拨动肠弦(激励方式:拨弦)→ 琴弦把振动传给蒙皮的琴身 → 木制船形琴身共鸣。", materials: "蒙皮的木制船形琴身、常雕成摩羯(makara)形的弯曲琴颈、肠弦。", usage: "抱于身前,用手指拨弹。", role: "旋律,为行吟者的歌唱伴奏。", players: "桑伽姆(Sangam)时代泰米尔社会的帕纳尔(panar)行吟者。", skills: "古代“pann”调式中的拨弦旋律。", scenes: "桑伽姆时代的宫廷与帕纳尔行吟者、寺庙仪式。", repertoire: "古代 pann 调式中的桑伽姆歌曲。", notation: "无传世记谱;pann 调式见于泰米尔文献的描述。", origin: "泰米尔人的古代弓形竖琴,在《脚镯记》(Silappatikaram)等桑伽姆文学中受到颂扬。", finds: "见于桑伽姆文学(约公元前300年至公元300年)和《脚镯记》;早期印度雕刻(如阿马拉瓦蒂)中出现弓形竖琴。", history: "文献描述了几种类型(periyazh、makarayazh 等);约7至10世纪被维纳琴取代,如今仅知于文献和复原品。", variants: "文献中列有 periyazh(21弦)、makarayazh、sakotayazh 和 sengottiyazh。", today: "已绝迹;仅见于文献和现代复原品。", uncertain: "其确切形制与音色存在争议,因为没有实物传世,文献也可有不同解读。", techniques: [{ name: "拨弦", how: "用手指拨动古代竖琴的琴弦。" }] },
"jantar": { sound: "柔和、嗡嗡作响、饱含持续音的拨弦音色,比鲁德拉维纳更轻、更明亮,垫在行吟者的歌声之下。", acoustics: "手指拨动金属丝弦(激励方式:拨弦)→ 琴弦在高品上振动 → 琴杆及其两只葫芦共鸣。", materials: "竹制或木制琴杆、两只葫芦、高品、金属丝弦。", making: "由演奏者或当地工匠以竹或木、两只葫芦和金属丝制成,品用蜡固定。", usage: "挂在肩上弹拨,歌者边唱边舞。", role: "为史诗演唱提供旋律与持续音。", players: "拉贾斯坦古贾尔(Gujar)族的博帕(bhopa)祭司兼行吟者。", skills: "在高品上弹奏持续音与旋律。", scenes: "德夫纳拉扬(Devnarayan)史诗演出、乡村仪式。", repertoire: "对着画卷演唱的德夫纳拉扬史诗(Devnarayan ki phad)。", origin: "拉贾斯坦带两只葫芦的民间棍形齐特琴,是鲁德拉维纳的近亲。", history: "古贾尔族博帕行吟者在演唱德夫纳拉扬史诗时演奏它。", today: "罕见,由少数博帕家族保存。", techniques: [{ name: "拨弦", how: "在高品上拨弦,发出弹跳的音色。" }, { name: "扫弦", how: "手指同时击奏数根弦。" }] },
"bansuri": { sound: "柔和、带气息、温暖而有木质感的音色,低音区带有空灵的气声边缘,高音区则清澈甜美;半按音孔产生梅恩德(meend)滑音,气息颤动则形成加马克(gamak)。", range: "约两个半八度;大型音乐会用班苏里笛的主音约在 E3,较小的民间笛音高得多。", tuning: "定调制作,按住最上方三个孔即得主音 Sa;拉格的其他音和微分音靠半按音孔和气息奏出。", acoustics: "气息吹过吹孔(激励方式:气流冲击边棱)→ 竹管中的空气柱振动 → 指孔改变其有效长度。", materials: "一整段竹子,开一个吹孔和六或七个指孔。", making: "取一整段薄壁竹子,用烧热的铁杆烙出孔洞,两端以线缠扎;由专门的笛匠制作,如在皮利比特和孟买。", usage: "横持,横吹吹孔,用指腹按住大孔。", role: "旋律,独奏或与塔布拉鼓、坦普拉琴合奏;在民间和电影音乐中是主奏乐器。", players: "民间乐师和牧人、宗教歌者以及古典独奏家。", skills: "半按指孔的梅恩德滑音、气息颤动的加马克、穆尔基(murki)与卡特卡(khatka)装饰音、长篇阿拉普。", scenes: "克里希纳颂歌、民间音乐、印度斯坦古典音乐会、电影音乐。", repertoire: "印度斯坦拉格演奏(帕纳拉尔·高希 Pannalal Ghosh、哈里普拉萨德·乔拉西亚 Hariprasad Chaurasia)、克里希纳颂歌和印地语电影音乐。", notation: "口传教学,以 sargam 辅助。", meaning: "克里希纳的笛子,其乐声吸引牧牛女(gopi);象征神圣之爱与灵魂的呼唤。", origin: "北印度和孟加拉的竹制横笛(bansi、murali),与吹笛的牧牛神克里希纳相关联。", history: "数千年来是民间与宗教笛子,20世纪由帕纳拉尔·高希、后来由哈里普拉萨德·乔拉西亚发展为古典音乐会乐器。", variants: "大小与调高多样,从小型民间 bansi 到低音班苏里笛;也有端吹的民间形制。", today: "仍广泛流传。", techniques: [{ name: "梅恩德(मींड)", how: "手指缓缓离开音孔,使音高在音与音之间滑行。" }, { name: "安多兰(आंदोलन)", how: "遮蔽一个音孔产生的缓慢音高摆动。" }, { name: "穆尔基(मुरकी)", how: "以快速指法奏出的短促回旋音。" }, { name: "超吹", how: "加强气息,升入高八度。" }] },
"venu": { sound: "清澈、明亮、灵活的笛音,比班苏里笛略少气声,带有快速的加马卡(gamaka)摆动和滑音。", range: "约两个半八度。", tuning: "定调制作,开八个指孔;卡纳提克拉格及其加马卡靠半按音孔和气息控制奏出。", acoustics: "气息吹过吹孔(激励方式:气流冲击边棱)→ 竹管内的空气柱振动 → 指孔改变其有效长度。", materials: "竹子,开一个吹孔和八个指孔。", making: "取薄壁竹子烙出孔洞;由南印度的专门笛匠制作。", usage: "横持,横吹吹孔。", role: "旋律,在卡纳提克音乐会和舞蹈乐队中独奏。", players: "卡纳提克音乐家;历史上也有寺庙和民间乐师。", skills: "半按音孔与气息产生的加马卡摆动、快速乐句、滑音。", scenes: "卡纳提克音乐会、寺庙节庆、婆罗多舞(Bharatanatyam)。", repertoire: "卡纳提克克里提(kriti)与阿拉帕纳、婆罗多舞音乐;T. R. 马哈林加姆(T. R. Mahalingam)和 N. 拉马尼(N. Ramani)是著名演奏家。", notation: "卡纳提克 sargam 记谱。", meaning: "与克里希纳(韦努戈帕拉 Venugopala,吹笛的牧牛人)相关联。", origin: "南印度的卡纳提克竹笛,泰米尔语称 kuzhal,见于桑伽姆文学。", finds: "kuzhal 见于桑伽姆文学(约公元前300年至公元300年)和《脚镯记》。", history: "泰米尔音乐中最古老的乐器之一,20世纪由 T. R. 马哈林加姆确立了它在卡纳提克音乐会舞台上的地位。", today: "仍活跃于卡纳提克音乐。", techniques: [{ name: "加马卡(கமகம்)", how: "半按音孔和手指滑动产生摆动的卡纳提克装饰音。" }, { name: "超吹", how: "加强气息,升入高八度。" }] },
"algoza": { sound: "明亮、带簧片感、执着的口哨式二重奏:一支管保持稳定的持续音,另一支管奏出活泼而富装饰的旋律,借助循环换气而不间断地发声。", range: "有限,旋律管约一个八度。", acoustics: "气息进入两条风道(激励方式:气流冲击边棱)→ 两支管笛的空气柱振动 → 指孔缩短旋律管的有效长度。", materials: "两支木制或竹制的哨笛,常绑在一起。", making: "两支木制或竹制哨笛,常由演奏者或当地工匠制作并绑在一起。", usage: "两支管同时含在口中,连续吹奏。", role: "旋律加持续音,为歌曲与舞蹈伴奏。", players: "牧人,以及朗加(Langa)、曼加尼亚尔(Manganiyar)、旁遮普和信德的民间乐师。", skills: "循环换气、持续音加旋律、快速的指法装饰音。", scenes: "放牧、民歌、婚礼与集市。", repertoire: "拉贾斯坦民歌和旁遮普民间舞曲(如 jugni 和 bhangra)。", origin: "成对合奏的哨笛,见于拉贾斯坦、旁遮普和信德。", history: "牧人和民间乐师以一支管作持续音、另一支管奏旋律;是朗加与曼加尼亚尔音乐的主干。", variants: "两管等长或不等长;信德与旁遮普的形制大小不同。", today: "仍流传,但熟练的演奏者很少。", techniques: [{ name: "循环换气", how: "用鼻吸气,使两支笛不间断地发声。" }, { name: "颤音", how: "快速的手指拍动,在持续音管之上装饰旋律。" }] },
"narh": { sound: "带气息的空洞笛音,同时伴有演奏者哼出的人声,形成嗡嗡的、双声部的幽灵般声响。", acoustics: "气息吹向管口边缘(激励方式:气流冲击边棱)→ 芦苇管中的空气柱振动;演奏者的声带加入哼出的持续音。", materials: "一根长长的 kair 芦茎,开四个指孔。", making: "由演奏者以沙漠植物 kair(一种长芦苇)的茎制成,开四个指孔。", usage: "斜持,横吹管口边缘,同时哼唱。", role: "带哼唱持续音的独奏旋律。", players: "拉贾斯坦西部和信德的牧人;仅有少数大师如卡尔纳·比尔(Karna Bhil)广为人知。", skills: "同时哼唱与吹奏、循环换气。", scenes: "牧人的独奏音乐、民间节庆。", repertoire: "牧人的独奏曲和民歌。", origin: "拉贾斯坦和信德沙漠牧人的长管边吹笛,以芦茎制成。", history: "演奏者边吹边哼持续音,形成双声部的声音;如今只有少数大师演奏。", today: "濒危。", techniques: [{ name: "人声与笛", how: "演奏者边吹边哼出持续音,人声与笛声同时发出。" }, { name: "超吹", how: "超吹时选取笛子的泛音作为旋律。" }] },
"shehnai": { sound: "尖锐、带鼻音、簧片感、哀婉的音色,强劲而明亮,有宽幅的梅恩德(meend)滑音和用嘴唇产生的揉音;能传到户外远处,既喜庆又忧伤。", range: "约一个半到两个八度。", tuning: "定调制作;微分音和拉格的音靠唇压和半按音孔塑造,并有一支持续音沙赫奈管配合。", acoustics: "气息和唇压使双簧片振动(激励方式:气息)→ 簧片开合 → 锥形管膛中的空气柱共鸣。", materials: "木制锥形管,开八或九个孔,双簧片,金属喇叭口。", making: "车制的木质锥形管,配外翻的金属喇叭口和棕榈叶双簧片,由北印度工匠(如瓦拉纳西)制作。", usage: "簧片含在唇间吹奏,通常配一支持续音沙赫奈管(“sur”)。", role: "旋律,另有一支沙赫奈管保持持续音。", players: "穆斯林世袭乐师家族,如比斯米拉·汗(Bismillah Khan)的家族。", skills: "循环换气、靠唇压产生的梅恩德与加马克、快速塔恩(taan)。", scenes: "婚礼、寺庙与宫殿门前、印度斯坦音乐会。", repertoire: "婚礼与吉庆音乐、瑙巴特(naubat)音乐、印度斯坦拉格和轻古典乐曲。", notation: "口传教学,以 sargam 辅助。", meaning: "吉祥之声:北印度婚礼上被认为非它不可。", origin: "北印度的唢呐类乐器,与波斯 surnā 相关,婚礼与寺庙中象征吉祥。", history: "在宫殿门前的“瑙巴特”乐队中演奏,20世纪由瓦拉纳西的比斯米拉·汗提升到古典音乐会的地位。", today: "仍流传,但在日常仪式中的使用正在减少。", techniques: [{ name: "梅恩德(मींड)", how: "唇压和半按音孔使音高在音与音之间滑行。" }, { name: "循环换气", how: "储存在腮中的气息使音色不间断。" }, { name: "穆尔基(मुरकी)", how: "由快速指法奏出的短促装饰性回旋音。" }] },
"nadaswaram": { sound: "极响亮、庄严而明亮的簧片音色,比沙赫奈管更深沉饱满,带有宽广的加马卡(gamaka)滑音;专为在户外传遍整个寺庙游行队伍而设。", range: "约两个半八度。", tuning: "定调制作;卡纳提克拉格通过唇与手指的控制以加马卡奏出,并有 ottu 或调音箱(sruti box)的持续音相伴。", acoustics: "气息使大型双簧片振动(激励方式:气息)→ 簧片开合 → 长锥形管膛和外翻的喇叭口共鸣。", materials: "阿查木(aacha,印度黑木)制的长锥形管身,开十二个孔,大簧片,木制或金属喇叭口。", making: "以阿查木(印度黑木)车制,配木制或金属喇叭口,簧片由干燥压制的芦草做成;库姆巴科南附近的纳拉辛加佩泰(Narasinghapettai)是著名的制作中心。", usage: "簧片松松含在唇间吹奏,常成对,并配持续音的“ottu”或调音箱。", role: "旋律,与塔维尔鼓的节奏和持续音相配。", players: "伊赛·韦拉拉(isai vellalar)社群的世袭寺庙乐师。", skills: "循环换气、加马卡、长篇拉格阿拉帕纳即兴。", scenes: "印度教寺庙仪式与游行、婚礼。", repertoire: "寺庙仪式音乐、马拉里(Mallari)游行乐曲和卡纳提克拉格阿拉帕纳;T. N. 拉贾拉特纳姆·皮莱(T. N. Rajarathinam Pillai)是著名演奏家。", notation: "卡纳提克 sargam 记谱。", meaning: "“吉祥乐器”(mangala vadyam):南印度的印度教寺庙仪式和婚礼少不了它的声音。", origin: "泰米尔纳德邦及南印度的大型双簧唢呐,寺庙中的吉祥乐器“mangala vadyam”。", history: "世袭的“伊赛·韦拉拉”乐师在寺庙和游行中演奏,总是与塔维尔鼓同行。", variants: "更长的 bari 那达斯瓦拉姆和较短的 timiri。", today: "仍活跃于寺庙和婚礼音乐;纳拉辛加佩泰的那达斯瓦拉姆获得了地理标志认证。", techniques: [{ name: "加马卡(கமகம்)", how: "唇与手指的控制产生宽广的卡纳提克装饰音。" }, { name: "循环换气", how: "储存在腮中的气息使长乐句不间断。" }] },
"harmonium": { sound: "稳定、带簧片感、管风琴般的音色,甜美而略带嗡鸣;音高固定,因此滑音靠快速的装饰音来模仿,持续音拉栓则加入连续的背景音。", range: "通常约三到三个半八度(常为39或42个键)。", tuning: "固定的十二平均律;有些制造商提供22 shruti 或可变音阶的型号。", acoustics: "手动风箱送出空气(激励方式:风)→ 黄铜自由簧片透过簧槽振动 → 木制箱体和簧室为声音增色。", materials: "带风箱的木箱、黄铜自由簧片、键盘。", making: "在加尔各答、德里、孟买和旁遮普的作坊手工制成,用木箱、布制风箱和黄铜簧片(传统上用进口的德国簧片或本地制的“帕利塔纳”簧片)。", usage: "置于地上;左手推拉风箱,右手弹键。", role: "紧随歌者的旋律伴奏,以及持续音。", players: "自弹自唱的歌者、基尔坦(kirtan)与卡瓦利(qawwali)乐师,以及印度斯坦声乐的伴奏者。", skills: "跟随歌者、持续音拉栓、快速的装饰性跑句。", scenes: "巴赞(bhajan)与基尔坦、卡瓦利、加扎尔与泰戈尔歌曲、戏剧。", repertoire: "巴赞、基尔坦、卡瓦利、加扎尔、戏剧歌曲(natya sangeet)和泰戈尔歌曲(Rabindrasangeet)。", origin: "1870年代由德瓦尔卡纳特·高斯(Dwarkanath Ghose)等人在加尔各答将欧洲脚踏风琴改制而成的手动簧风琴。", history: "尽管对其固定音高有争议,它仍成为北印度宗教、轻古典和苏菲音乐中无处不在的乐器。", variants: "便携的手动箱式簧风琴、可变音阶型号和脚踏风琴。", today: "仍广泛流传;曾因音高固定而被全印广播电台禁用(1940–1971年)。", techniques: [{ name: "持续和弦", how: "推拉风箱使多片簧片持续发声成和弦。" }, { name: "持续音拉栓", how: "持续音拉栓在旋律之下保持主音。" }] },
"sruti-petti": { sound: "连续、稳定、带簧片感的持续音,柔和如管风琴,没有起音,也没有旋律。", range: "主音、其五度及各八度的固定持续音,由拉栓选择。", tuning: "依演奏者的主音 Sa 定音;拉栓选择 Sa、Pa 或 Ma。", acoustics: "手动风箱送出空气(激励方式:风)→ 黄铜自由簧片振动 → 小木箱为声音增色。", materials: "带风箱和自由簧片的木箱;拉栓选择持续音。", making: "由南印度作坊以木箱、风箱和黄铜簧片制成。", usage: "手动推拉,连续发出主音和五度音。", role: "持续音。", players: "那达斯瓦拉姆乐队的伴奏者、卡纳提克歌者和宗教团体。", skills: "稳定地推拉风箱、依演奏者音高调音。", scenes: "寺庙那达斯瓦拉姆音乐、卡纳提克声乐音乐会、宗教歌唱。", repertoire: "垫在那达斯瓦拉姆寺庙音乐和卡纳提克歌唱之下。", origin: "南印度的小型手动簧风琴,用来发出恒定的持续音。", history: "在许多那达斯瓦拉姆乐队中取代了“ottu”持续音唢呐,并为卡纳提克歌者充当坦普拉琴的替代品。", variants: "手动箱式和电子调音箱,如今非常普遍。", today: "仍在使用,但大多已被电子持续音箱取代。", techniques: [{ name: "持续音", how: "风箱使主音和五度音作为稳定的持续音不断发声。" }] },
"pakhawaj": { sound: "深沉、温暖而开阔:涂有面团的左侧鼓面发出轰鸣的低音,可通过手掌按压而滑音,右侧鼓面则以清晰有音高的音色鸣响。击法从共鸣的开放音“dha”到干脆的闷击拍打,整体声音比塔布拉鼓更宽广、不那么清脆。", range: "右侧鼓面定在乐曲的主音,比塔布拉鼓低;左侧鼓面发出无固定音高的深沉低音,手掌可将其向上滑弯。", tuning: "用锤敲击绳扣下的皮制绷带和木块,将右侧鼓面定在独奏者的主音(Sa);低音鼓面上的小麦面团在每场演出时现涂。", acoustics: "手掌与手指击打 → 两张绷紧的羊皮鼓面(右侧带有硬化的 syahi 鼓心,使其泛音成谐波)→ 木制桶形鼓身。", materials: "蒙羊皮鼓面的木制桶形鼓身、一面上的黑色调音糊 syahi、低音鼓面上的小麦面团、皮绳。", making: "鼓身由整段原木车制并掏空,复合鼓面、绳扣和 syahi 糊由专门的制鼓匠制作,他们也负责换皮与修理。", usage: "横放,双手掌与手指并用演奏。", role: "节奏:保持塔拉(tala)周期,并为德鲁帕德(dhrupad)歌唱和器乐阿拉普—卓尔—恰拉即兴终止式与独奏段落。", players: "世袭家族流派(如纳特德瓦拉 Nathdwara 与库道·辛格 Kudau Singh 传统)的专业打击乐手,以及毗湿奴派“哈维利音乐”(haveli sangeet)的寺庙乐师。", skills: "开掌击法 bol、共鸣的低音击法、复杂的塔拉周期与帕兰(paran)。", scenes: "德鲁帕德音乐会、寺庙礼拜、卡塔克舞。", repertoire: "德鲁帕德与达马尔(dhamar)、毗湿奴派哈维利音乐、卡塔克舞,以及恰乌塔尔(chautal,12拍)和达马尔(14拍)等周期中的独奏“帕兰”。", notation: "击法以口诀音节(bol)口诵并书写,如 dha、dhet、kita、taka、gadi、gina,先念诵再演奏。", origin: "北印度的双面桶形鼓,源自古代的姆里丹加(mridang)。", history: "为德鲁帕德和鲁德拉维纳伴奏,也在毗湿奴派寺庙中演奏;被认为是塔布拉鼓的祖先。", variants: "南印度的姆里丹加(mridangam)是近亲;北印度各地也有同样形状的寺庙与民间桶鼓。", today: "仍流传但较专门,主要靠德鲁帕德复兴和卡塔克舞而延续。", techniques: [{ name: "开放低音击法", how: "手掌击打涂有小麦面团的低音鼓面,发出深沉的轰鸣。" }, { name: "闷击", how: "手掌停留在鼓面上,发出短促干脆的拍打声。" }, { name: "雷拉(रेला)", how: "极快的连串击法,如滚奏般的急风骤雨。" }] },
"dhak": { sound: "响亮、轰鸣而清脆的鼓声:细鼓槌在鼓面上发出脆响,其下是深沉滚动的鼓身声,快速节奏汇成推动人心的轰响,传遍整个街区。", range: "无固定音高,响亮而深沉。", acoustics: "细鼓槌敲击 → 皮制鼓面(另一面随之共振)→ 大型木制桶形鼓身。", materials: "木制桶形鼓身,山羊皮或水牛皮鼓面,竹或藤制鼓槌。", making: "由当地制鼓匠以挖空的木桶和绳绷的皮面制成;杜尔加节(Durga Puja)时以白色羽毛缨饰装饰。", usage: "挂在肩上或置于膝上,以两支细鼓槌敲击。", role: "节奏与信号:宣告并推动节日的仪式与舞蹈。", players: "称为 dhaki 的世袭职业鼓手,多来自孟加拉乡村,在节日季节前往城市。", skills: "快速的鼓槌节奏、边击鼓边舞蹈。", scenes: "杜尔加节及其他节庆、游行。", repertoire: "杜尔加节各阶段的仪式节奏,包括傍晚礼拜的“arati”节奏,以及手持香炉的 dhunuchi 舞。", meaning: "它的声音与杜尔加女神降临孟加拉密不可分;每个祭典委员会或家庭都会雇请 dhaki。", origin: "孟加拉和阿萨姆的大型桶形鼓。", history: "挂在颈上,以羽毛装饰,是杜尔加节的声音,由世袭的“dhaki”鼓手演奏。", variants: "大小因村而异;dhol 是较小的相关桶鼓,流行于北印度和东印度各地。", today: "仍流传,与加尔各答的杜尔加节紧密相连,该节日于2021年被联合国教科文组织列为非物质文化遗产。", techniques: [{ name: "鼓槌击法", how: "两支细鼓槌敲击鼓面,发出响亮轰鸣的节拍。" }, { name: "滚奏", how: "快速连击,在祭典上形成持续的轰响。" }] },
"thavil": { sound: "极其响亮而明亮:鼓槌一面发出尖锐的脆响,戴指套的右侧鼓面则以轰鸣共鸣的音色鸣响。快速的滚奏与重音与那达斯瓦拉姆一起穿透露天游行的喧嚣。", range: "无固定音高,响亮;右侧鼓面深沉悠长,左侧鼓面高而干。", acoustics: "硬化的指套和短鼓槌敲击 → 两张由鼓箍和绳扣绷紧的皮制鼓面 → 短而宽的菠萝蜜木鼓身。", materials: "菠萝蜜木鼓身、山羊皮或水牛皮鼓面;右手戴硬化指套,左手用鼓槌。", making: "菠萝蜜木鼓身由专门的匠人雕成;鼓面绷在竹制或金属鼓箍上,以绳扣拉到极高的张力。", usage: "挂在肩上;右手用指套击打,左手用鼓槌。", role: "节奏:在“大乐队”(periya melam)中与那达斯瓦拉姆配合,为阿拉帕纳和克里提伴奏,并担任节奏独奏。", players: "泰米尔纳德邦的世袭寺庙乐师,传统上来自伊赛·韦拉拉社群,在师徒传承中受训。", skills: "复杂的塔拉即兴、“tani avartanam”独奏、有力的滚奏。", scenes: "寺庙游行与仪式、婚礼。", repertoire: "大乐队风格的卡纳提克克里提、日常礼拜与节庆的寺庙仪式音乐,以及婚礼“mangala isai”。", meaning: "它与那达斯瓦拉姆的合奏被视为吉祥(mangala vadyam),婚礼与寺庙典礼上必须听到。", origin: "泰米尔纳德邦的桶形鼓,总是与那达斯瓦拉姆搭档。", history: "由世袭乐师在寺庙和婚礼音乐中演奏,声音响亮,足以用于户外游行。", variants: "泰米尔纳德邦、喀拉拉邦以及斯里兰卡泰米尔侨民的形制在大小上略有差异。", today: "仍活跃于南印度的寺庙和婚礼音乐。", techniques: [{ name: "鼓槌击法", how: "鼓槌击打右侧鼓面,发出尖锐响亮的脆响。" }, { name: "指击", how: "戴指套的手指击打左侧鼓面,发出响亮的拍击声。" }, { name: "滚奏", how: "快速连击,形成雷鸣般的滚奏。" }] },
"ghanta": { sound: "明亮、高亢、持续的金属铃声,余音闪烁;阿拉蒂(aarti)时不断摇铃,在诵经与鼓声之上形成稳定的叮铃声浪。", range: "单一的高铃音,带非谐波泛音;大型寺庙铜钟更低沉。", acoustics: "摆动的铃舌撞击 → 铸青铜铃体 → 直接向外辐射。", materials: "铸青铜或黄铜,内有铃舌。", making: "以黄铜或钟铜(铃青铜)用失蜡法或砂型铸造,铃柄常以迦楼罗(Garuda)、南迪(Nandi)或其他神明的坐骑为顶。", usage: "握柄摇动,用于供奉的阿拉蒂(aarti)。", role: "信号:标示礼拜的时刻,并为献灯伴奏。", players: "祭司和礼拜(puja)中的家庭成员。", skills: "在整个仪式中稳定摇铃。", scenes: "寺庙与家中礼拜、阿拉蒂。", repertoire: "整个阿拉蒂和日常礼拜中与法螺一起摇响。", meaning: "据说其声音能召唤神明、驱除邪祟;信徒入寺时会摇响寺庙的铃。", origin: "印度教礼拜(puja)时摇响的仪式手铃。", history: "自古用于寺庙与家庭仪式,铃柄常以神明坐骑的形象为顶;大钟悬挂在寺庙入口。", variants: "家中神龛用的小手铃、寺庙入口悬挂的大钟;佛教的金刚铃(drilbu)是相关的仪式铃。", today: "仍用于印度教和佛教的日常礼拜。", techniques: [{ name: "摇铃", how: "摇动手铃,铃舌撞击发出明亮的响声。" }] },
"ghungroo": { sound: "清脆、高亢的叮铃闪响;一步落地发出尖锐成簇的碰撞声,通过控制脚跟和脚尖的动作,可以从一声细小的叮当变化为轰响的震颤。", range: "无固定音高,高亢。", acoustics: "脚步的摇动或踏地 → 松动的金属小丸 → 撞击小黄铜铃的壁。", materials: "串在绳上或缝在皮垫上的小黄铜铃。", making: "小黄铜丸铃经铸造或冲压后,串在棉绳上或缝在皮垫或布垫上;卡塔克舞者每只脚踝常戴100个或更多。", usage: "系在脚踝上,由脚步动作发声。", role: "节奏:舞者的双脚成为额外的打击声部,与鼓相应答。", players: "古典舞和民间舞的舞者。", skills: "精准的脚步“塔特卡”(tatkar),可奏出单个铃声或整串铃响。", scenes: "卡塔克舞与婆罗多舞、民间舞蹈、莫卧儿宫廷。", repertoire: "卡塔克的塔特卡与提海(tihai)、婆罗多舞的贾蒂(jati)以及许多民间舞蹈。", meaning: "舞者准备好表演时,由上师(guru)郑重授予脚铃,须以敬意相待,不可用脚触碰。", origin: "印度古典舞者与民间舞者佩戴的成串小金属脚铃。", history: "卡塔克、婆罗多舞等舞者佩戴脚铃,使其脚步成为节奏的一部分。", variants: "卡塔克的多铃长串、婆罗多舞的铃垫,以及各地区的民间脚链。", today: "仍遍及印度各种舞蹈。", techniques: [{ name: "踏步", how: "舞者的脚步摇动脚铃,形成清晰的节奏型。" }] },
"manjira": { sound: "敞击时发出明亮、高亢、响亮的“叮”声,闷击时则是短促干脆的“嚓”声;两者交替标示塔拉(tala),为宗教歌曲增添闪烁的金属层次。", range: "无固定音高,高亢,金属音响亮。", acoustics: "两片小而厚的钹以边缘或面撞击 → 青铜片振动 → 直接向外辐射。", materials: "两个以绳相连的小而厚的青铜或黄铜碗。", making: "由金属工匠铸造或锤打青铜或黄铜而成;南印度的 talam 是更重的铸造碗形钹。", usage: "相互敲击,敞击或闷击,以标示塔拉。", role: "节奏:保持节拍与塔拉周期。", players: "宗教歌者、寺庙乐师、民间乐师,以及指挥婆罗多舞的纳图瓦纳尔(nattuvanar)。", skills: "标示塔拉周期各拍的敞击与闷击。", scenes: "巴赞(bhajan)与基尔坦(kirtan)、民歌、寺庙音乐、婆罗多舞。", repertoire: "巴赞与基尔坦、婆罗多舞的纳图万伽姆(nattuvangam)和民歌。", origin: "印度的小型手钹,北方称 manjira,南方称 talam 或 jalra。", history: "数千年来用于宗教音乐;在南印度,“纳图瓦纳尔”以 talam 引领婆罗多舞。", variants: "北方有 manjira 与 jhanj,南方有 jalra 与 talam;大小从微小的指钹到较大的寺庙钹不等。", today: "遍及宗教音乐与舞蹈音乐,仍在使用。", techniques: [{ name: "敞击", how: "两片小钹边对边相击而鸣。" }, { name: "闷击", how: "两片钹压在一起,发出短促的咔嗒声。" }] },
"kartal": { sound: "干燥、尖锐的木击声,夹杂着金属片的叮当;快速拍击形成奔驰般噼啪作响的声流。", range: "无固定音高。", acoustics: "手持的两块板相互撞击 → 木头与响片振动 → 直接向外辐射。", materials: "成对的木块配小金属片,或黄铜钹。", making: "用硬木雕成,槽中嵌小黄铜片,或铸成小钹;由乡村工匠制作。", usage: "双手各持一件相互拍击。", role: "节奏。", players: "宗教歌者、流浪的包尔(Baul)和基尔坦歌者,以及曼加尼亚尔(Manganiyar)等拉贾斯坦民间乐师。", skills: "快速的拍击节奏与滚奏。", scenes: "基尔坦与巴赞、包尔歌曲、拉贾斯坦民间音乐。", repertoire: "基尔坦与巴赞、包尔歌曲、拉贾斯坦民歌。", origin: "带响片的木制拍板或小钹,用于孟加拉、拉贾斯坦和马哈拉施特拉的宗教歌唱。", history: "流浪的信徒和包尔歌者在基尔坦中用它打拍子,这一做法与柴坦尼亚(Chaitanya)运动相关。", variants: "拉贾斯坦和古吉拉特用带响片的木拍板,孟加拉和马哈拉施特拉用小钹。", today: "仍在使用。", techniques: [{ name: "拍击", how: "带响片的木拍板按节奏型相互拍击。" }, { name: "滚奏", how: "快速摇动发出咔嗒声,形成连续的震颤。" }] },
"shankh": { sound: "响亮、圆润而穿透力强的号角声,通常是一个长长渐强的音,可以弯曲和脉动;数支同吹则形成摇曳、持续低鸣的合唱。", range: "基本上只有一个音(带几个微弱的泛音),音高由螺壳大小决定。", acoustics: "颤动的嘴唇 → 螺旋形螺壳内的空气柱(顶端开口)→ 从壳口向外辐射。", materials: "大型神圣的法螺(chank)或其他海螺壳,有时配金属吹口。", making: "将大型神圣法螺(Turbinella pyrum)的顶端磨掉形成吹孔;寺庙法螺常镶以黄铜或银。", usage: "从顶端用颤动的嘴唇吹奏。", role: "信号:开启礼拜、典礼与游行。", players: "祭司、家庭成员,在孟加拉则是家中的女性,于黄昏和婚礼时吹响。", skills: "长而渐强的单音和泛音召唤。", scenes: "寺庙礼拜与阿拉蒂(aarti)、婚礼、杜尔加节、高棉王室典礼。", repertoire: "阿拉蒂与礼拜、孟加拉婚礼、杜尔加节;在柬埔寨,khyang 在王室仪式上吹响。", meaning: "为毗湿奴所神圣化,其法螺名为潘查扎尼亚(Panchajanya);是佛教八吉祥之一,其声被认为能净化。", origin: "印度教与佛教的南亚及东南亚海螺号,高棉语称 khyang。", history: "《摩诃婆罗多》中吹响它以开战,寺庙中吹响以开始礼拜,为毗湿奴所神圣化;也是高棉宫廷与仪式音乐的一部分。", variants: "右旋的海螺尤为珍贵;藏语的 dungkar(法螺)是佛教仪式中的同一种乐器。", today: "仍用于印度教和佛教礼拜。", techniques: [{ name: "吹奏", how: "用颤动的嘴唇吹响海螺,发出长长上扬的号声。" }, { name: "唇滑音", how: "改变唇压使号声弯曲。" }] },
"kombu": { sound: "粗犷、嘹亮的铜管号声,响亮而边缘粗糙,通常是短促的泛音爆发或长音;一排孔布号与鼓相应答,形成轰鸣而喜庆的声墙。", range: "弯管的少数自然泛音;没有指孔。", acoustics: "颤动的嘴唇 → 弯曲锥形金属管中的空气柱 → 外翻的喇叭口。", materials: "分节弯制的黄铜或紫铜。", making: "由金属匠人将黄铜或紫铜管节接成 C 形或 S 形弯管,常为可套接的分段。", usage: "成组用颤动的嘴唇吹奏,发出几个泛音。", role: "信号与色彩:为寺庙鼓乐的节奏周期断句。", players: "喀拉拉邦和泰米尔纳德邦的寺庙与节庆乐师。", skills: "与鼓交替的泛音号声。", scenes: "寺庙节庆、游行、喀拉拉的潘查瓦迪亚姆(panchavadyam)。", repertoire: "喀拉拉的潘查瓦迪亚姆(与 timila、maddalam、ilathalam 和 idakka 合奏)以及寺庙节庆中的“kombu pattu”。", origin: "喀拉拉邦和泰米尔纳德邦的 C 形或 S 形金属号角。", history: "在潘查瓦迪亚姆等寺庙节庆乐队以及有大象的游行中演奏。", variants: "喀拉拉的 C 形孔布号,以及泰米尔和卡纳塔克的 S 形形制。", today: "仍活跃于喀拉拉的寺庙节庆,如特里苏尔普兰(Thrissur Pooram)。", techniques: [{ name: "吹奏", how: "颤动的嘴唇吹出号角的自然音,发出响亮的号声。" }, { name: "超吹", how: "收紧嘴唇跳到更高的分音。" }] },
"nagara": { sound: "雷鸣般而有力:大鼓发出深沉的轰鸣,小鼓则清脆尖锐,快速交替的滚奏汇成令人振奋的隆隆声,传遍整个集市。", range: "实际上无固定音高;小鼓高而干,大鼓深沉轰鸣。", acoustics: "鼓槌敲击 → 以绳绷紧的皮制鼓面 → 封闭的碗形釜鼓壳。", materials: "铁、铜或陶制鼓碗,蒙以绳绷的水牛皮或山羊皮鼓面;木制或藤制鼓槌。", making: "鼓釜由铁皮或铜皮锤打而成,或用烧制的陶土制成,由当地制鼓匠蒙上绳绷或带绑的皮面。", usage: "置于地面,双槌敲击,小鼓音高、大鼓音低。", role: "节奏与信号:开启节庆并推动民间舞蹈,小鼓在大鼓的低音之上演奏节奏型。", players: "拉贾斯坦和北方邦的世袭职业鼓手;普什卡的纳图拉尔·索兰基(Nathulal Solanki)是知名的当代大师。", skills: "两鼓之间滚动交错的击法、渐快的节庆节奏。", scenes: "寺庙仪式、乡村集市、洒红节(Holi)与婚礼、民间舞蹈。", repertoire: "寺庙与节庆节奏、洒红节歌曲以及拉贾斯坦的民间舞蹈。", origin: "拉贾斯坦和北印度民间音乐的成对釜鼓,是波斯 naqqara 的地方形制。", history: "在拉贾斯坦的寺庙、集市和王室城堡演奏,大型 nagara 也曾为拉杰普特军队鸣响,至今仍用于开启节庆。", variants: "民间音乐用成对的小型 nagara,寺庙和宫殿用大型的“nagaru”和“bam”釜鼓。", today: "仍活跃于拉贾斯坦和北印度的民间音乐。", techniques: [{ name: "鼓槌击法", how: "两支鼓槌敲击釜鼓,发出响亮共鸣的轰鸣。" }, { name: "滚奏", how: "快速连击,如滚滚雷声。" }] },
"rabab": { sound: "深沉、弹跳而共鸣:皮制面板带来有力明亮的起音和迅速的衰减,透过共鸣弦的光晕继续鸣响。快速拨片跑句清脆而有推动力,空弦持续音则发出低沉的嗡鸣。", range: "从低主音起约两到三个八度,另有长持续音弦和约十几根共鸣弦。", tuning: "三根主旋律弦、两三根长持续音弦以及11至15根依所奏调式或拉格定音的共鸣弦。", acoustics: "拨片拨弦 → 肠弦或尼龙弦 → 越过绷在深雕琴碗上的羊皮膜上的琴码;钢制共鸣弦共鸣。", materials: "整根桑木掏制的琴身、羊皮面板、肠制演奏弦和钢制共鸣弦、木制或骨制拨片。", making: "琴身、琴颈和弦轴箱由喀布尔、伊斯塔利夫(Istalif)和白沙瓦作坊的工匠以整根桑木雕成,再蒙上羊皮并镶嵌骨或贝。", usage: "横置于膝上,用拨片弹拨。", role: "旋律:阿富汗艺术音乐与民间音乐中的主奏乐器,也为歌唱伴奏。", players: "喀布尔卡拉巴特(Kharabat)街区的职业乐师和普什图民间乐师;锡克教传统中的拉巴比(Rababi)家系出自巴伊·马尔达纳(Bhai Mardana)。", skills: "快速拨片跑句、空弦持续音、节奏性扫弦。", scenes: "莫卧儿与苏丹国宫廷、锡克教与苏菲宗教音乐、阿富汗与普什图歌曲。", repertoire: "阿富汗古典的“naghma”和“raga”、普什图民歌、拉巴比传统中的锡克教圣歌(gurbani)基尔坦;乌斯塔德·穆罕默德·奥马尔(Ustad Mohammad Omar)是20世纪著名的大师。", meaning: "普什图人和塔吉克人视之为其音乐的核心,有时称为“乐器之狮”。", origin: "阿富汗和普什图人地区的短颈拨弦鲁特琴,束腰琴身,皮制面板。", history: "由阿富汗和印度—波斯乐师带入北印度,是莫卧儿德鲁帕德乐师的“塞尼热瓦普”(seni rabab),也是萨罗德琴的祖先;古鲁那纳克(Guru Nanak)的同伴马尔达纳也演奏热瓦普。", variants: "阿富汗(喀布尔)热瓦普、帕米尔与巴达赫尚热瓦普,以及德鲁帕德乐师的印度“塞尼热瓦普”。", today: "仍流传;热瓦普的制作与演奏艺术于2024年由阿富汗、伊朗、塔吉克斯坦和乌兹别克斯坦联合列入联合国教科文组织名录。", techniques: [{ name: "拨弦", how: "拨片拨动旋律弦,发出深沉共鸣的弹拨声。" }, { name: "共鸣回响", how: "每个音之后共鸣弦继续鸣响。" }, { name: "颤音", how: "快速交替拨奏使音持续。" }] },
"surnay": { sound: "尖锐、带鼻音、极为响亮,专为户外而设:明亮的簧片嗡鸣,借循环换气毫无停顿,在定音鼓的节拍之上充满装饰音、颤音和滑音。", range: "约一个半八度。", tuning: "七个指孔加一个拇指孔给出自然音阶或调式音阶;波斯与印度的调式靠半按音孔和唇压塑造。", acoustics: "气息 → 小型双簧片(嘴唇抵在一个圆盘上)→ 锥形木制管膛 → 外翻的喇叭口。", materials: "锥形木身、金属簧管上的小双簧片、唇盘、外翻的喇叭口。", making: "以杏木或桑木等硬木车制;簧片由芦苇折成并绑在金属簧管上。", usage: "在户外大声吹奏,嘴唇抵在唇盘上。", role: "旋律:在鼓和长号之上吹奏号曲与乐调。", players: "宫廷鼓乐房(naqqarakhana 或 naubat khana)以及婚礼与节庆的世袭乐师。", skills: "循环换气、带装饰的号曲与旋律。", scenes: "宫殿门前的瑙巴特(naubat)典礼、军队进行曲、婚礼与节庆。", repertoire: "在宫殿与圣祠门前报时的瑙巴特典礼、军乐、婚礼与节庆舞蹈。", origin: "波斯的户外唢呐(surnā,“节庆之管”),经德里苏丹国和德干宫廷传入印度。", history: "在瑙巴特鼓乐房和军乐队中与定音鼓、长号一起演奏;是沙赫奈管、唢呐以及许多双簧管乐器的祖先。", variants: "遍及亚洲和非洲的大家族:zurna、sornā、唢呐、shehnai、ghaita、hne、sralai 和 serunai。", today: "其后裔仍在使用;瑙巴特演奏在一些苏菲圣祠仍有留存。", techniques: [{ name: "循环换气", how: "储存在腮中的气息使声音不间断。" }, { name: "滑音", how: "唇压使尖锐的音高弯曲。" }] },
"ghichak": { sound: "带鼻音、簧片感、略显粗犷的弓弦音色,带有嗡嗡的边缘,因共鸣弦的回响而更为丰厚;以滑音和快速装饰音歌唱。", range: "约两个八度。", tuning: "两三根演奏弦,通常按四度或五度定弦;阿富汗形制的共鸣弦依调式定音。", acoustics: "马尾弓 → 金属弦 → 皮面或木面板上的琴码 → 以尖柱支撑的圆形共鸣体。", materials: "木头、葫芦甚至铁皮罐制成的圆形琴身,配皮面或木面板、尖柱、金属弦、马尾弓。", making: "民间制作者用木头、葫芦,在阿富汗甚至用回收的铁皮罐做琴身,配长琴颈和铁尖柱。", usage: "竖持,以尖柱着地,转动琴身迎向弓。", role: "旋律,为歌唱与舞蹈伴奏。", players: "波斯、阿富汗和中亚的民间与职业乐师。", skills: "带装饰的旋律、滑音以及共鸣弦上的持续音。", scenes: "宫廷合奏、苏菲聚会、中亚民间与婚礼音乐。", repertoire: "塔吉克、乌兹别克和阿富汗民歌,以及用艾捷克(ghijak)演奏的塔吉克—乌兹别克十二木卡姆(shashmaqom)曲目。", origin: "波斯与中亚的尖柱提琴(ghichak、ghijak),流行于波斯人、塔吉克人、乌兹别克人和阿富汗人之中。", history: "中世纪起就见于波斯文献,随中亚乐师传入德里和德干宫廷;与卡曼切(kamancheh)相关。", variants: "乌兹别克—塔吉克的 ghijak、阿富汗以铁皮罐或木头为琴身的 ghichak,以及作为近亲的波斯卡曼切。", today: "仍活跃于中亚音乐。", techniques: [{ name: "滑音", how: "手指沿琴弦在音与音之间滑动。" }] },
"biola": { sound: "明亮、歌唱般的小提琴音色,以马来风格演奏,带有宽广的滑音、颤动的揉弦和紧凑的装饰音(bunga),紧随人声。", range: "G3–E7,但马来演奏多处于较低的两个八度。", tuning: "按五度 G–D–A–E 定弦;演奏建立在受中东和葡萄牙音乐影响的音阶上的马来阿斯里(asli)和乔格特(joget)旋律。", acoustics: "马尾弓 → 钢弦或肠弦 → 云杉面板上的琴码 → 中空的小提琴琴身。", materials: "云杉与枫木的小提琴琴身、四根弦、马尾弓。", making: "多为进口或工厂制造的小提琴;马来西亚和印度尼西亚也有一些本地制作者。", usage: "架在肩上,有时抵在胸前,用弓拉奏。", role: "旋律:与歌者重叠并应答。", players: "马来乐队中的职业与业余乐师。", skills: "马来风格的装饰音“bunga”、跟随歌者的滑音与揉弦。", scenes: "马来加扎尔(ghazal)与乔格特舞、婚礼、隆格英(ronggeng)与戏剧。", repertoire: "阿斯里歌曲、乔格特舞、马来加扎尔、隆格英、dondang sayang 以及班萨万(bangsawan)戏剧音乐。", origin: "16世纪葡萄牙人到达马六甲后,欧洲小提琴被马来世界采用(马来语 biola,源自葡萄牙语 viola)。", history: "成为马来加扎尔、乔格特、阿斯里以及受玛雍(mak yong)影响的音乐和马来戏剧乐队的主奏乐器。", today: "仍活跃于马来传统音乐和流行音乐。", techniques: [{ name: "滑音", how: "手指在音与音之间滑动,如马来歌曲中那样。" }, { name: "揉弦", how: "摇动手指使音微微颤动。" }] },
"saung-gauk": { sound: "柔和、温暖而亲切的拨弦音色,起音略带嗡嗡的丝质感,余音轻柔回响;左手按弦可产生小幅弯音,涟漪般的跑句听来细腻而不响亮。", range: "十六根弦,约三个八度。", tuning: "沿琴颈滑动弦的绳环来调整每根弦;竖琴可重新调为缅甸的调式,如 hnyin lone、aung myin 和 pale。", acoustics: "手指拨弦 → 丝弦或尼龙弦 → 连接到蒙鹿皮的面板,下为船形中空琴身。", materials: "蒙鹿皮的船形紫檀木琴身、弯曲的相思木根琴颈、以红绳系结的丝弦或尼龙弦。", making: "曼德勒和仰光的名匠掏空紫檀木琴身,绷上鹿皮,装上弯曲的相思木根琴颈,并以金箔和红流苏装饰。", usage: "置于膝上,琴颈在左;右手指拨弦,左手在琴颈处按弦以升高音高。", role: "古典歌曲的旋律与伴奏,作独奏或室内乐乐器。", players: "过去为宫廷乐师;今天为职业与学生竖琴手,男女皆有,如20世纪大师因莱·敏昂(Inle Myint Maung)。", skills: "左拇指按弦以改变音高、止音、涟漪般的琶音。", scenes: "王室宫廷室内乐、古典歌曲“玛哈吉塔”(Mahagita)、现代独奏会。", repertoire: "古典歌曲集《玛哈吉塔》(မဟာဂီတ),包括 kyo、bwe 和 patpyo 歌曲,以及现代独奏改编曲。", notation: "《玛哈吉塔》的歌词有书面记录,但旋律由老师口传耳授。", meaning: "缅族视之为最高贵的乐器,是古典文化的象征。", origin: "缅甸的弓形竖琴,源自古印度竖琴;骠国及后来的缅族宫廷曾演奏它。", finds: "公元前2世纪的印度浮雕中已出现弓形竖琴;唐代记载描述了802年到访长安的骠国乐师中的竖琴。", history: "它是古印度谱系中仅存的活态弓形竖琴;古典曲目《玛哈吉塔》在贡榜王朝宫廷中被整理定型,竖琴从13弦增至16弦。", today: "仍流传;在仰光和曼德勒的国立文化学校中教授。", techniques: [{ name: "按音", how: "左拇指在琴颈附近按弦以升高音高。" }, { name: "止音", how: "左手按住琴弦,得到短促的闷音。" }, { name: "泛音", how: "拨弦时轻触琴弦,发出柔和的泛音。" }] },
"hne": { sound: "响亮、尖锐、带鼻音,簧片音色明亮嗡鸣;其演奏充满俯冲般的滑音和鼓声之上的快速颤音,借循环换气而无间断地持续。", range: "约一个半八度。", tuning: "前面七个指孔和一个拇指孔;依随缅甸 hsaing 乐队的调式,用嘴唇弯音。", acoustics: "气息 → 口中的棕榈叶双簧片 → 锥形木制管膛 → 松套的外翻金属喇叭口。", materials: "锥形木身,开七个孔,大型可拆卸金属喇叭口,棕榈叶双簧片。", making: "以硬木车制,配单独的金属喇叭口和演奏者自己用棕榈叶折成的簧片。", usage: "簧片整个含在口中吹奏,常用循环换气。", role: "旋律:缅甸 hsaing waing 乐队的主奏管乐器。", players: "职业 hsaing 乐师,传统上为男性。", skills: "循环换气、灵活的滑音与装饰音。", scenes: "hsaing waing 乐队、佛塔节庆、zat pwe 戏剧、纳特(nat)精灵仪式。", repertoire: "用于节庆、zat pwe 戏剧、舞蹈和纳特精灵仪式的 hsaing waing 音乐。", origin: "缅甸的唢呐,属西亚和南亚的 surnay 家族,有大型“hne gyi”和小型“hne galay”两种尺寸。", history: "在节庆、舞蹈和戏剧的户外“hsaing waing”乐队中担任旋律。", variants: "大型的 hne gyi 和较小的 hne galay。", today: "仍活跃于缅甸的仪式与戏剧音乐。", techniques: [{ name: "循环换气", how: "储存在腮中的气息使尖锐的音色不间断。" }, { name: "滑音", how: "唇压和半按音孔使音高弯曲。" }] },
"tayaw": { sound: "甜美、歌唱般的小提琴音色,被改造成缅甸风格:频繁的滑音、快速的回旋音和轻柔的揉弦,跟随竖琴或人声,而非西方式的连奏线条。", range: "小提琴为 G3–E7,多在较低的两个八度演奏。", tuning: "为适应缅甸调式和乐队音高而重新定弦,而非标准的 G–D–A–E。", acoustics: "马尾弓 → 琴弦 → 木面板上的琴码 → 中空琴身。", materials: "木制提琴琴身、金属弦或肠弦、马尾弓。", usage: "用弓拉奏,架在肩上或竖持。", role: "旋律,为古典歌曲伴奏或带领流行乐队。", players: "职业古典与流行音乐家。", skills: "追随缅甸弯琴(saung gauk)或人声的缅甸式滑音与装饰音。", scenes: "古典歌曲伴奏、戏剧、流行音乐。", repertoire: "《玛哈吉塔》古典歌曲伴奏、戏剧与缅甸流行歌曲。", origin: "在缅甸,“tayaw”指弓弦提琴:既有较古老的尖柱提琴,也有19世纪以来按缅甸调弦改造的西方小提琴。", history: "小提琴在贡榜王朝诸王时期随欧洲人的接触传入,融入缅甸古典与流行音乐。", today: "仍在使用。", uncertain: "较早的文献用这个词指一种本土尖柱提琴,其确切形制记载甚少。", techniques: [{ name: "滑音", how: "手指沿琴弦滑动,模仿人声。" }, { name: "揉弦", how: "摇动手指使音微微颤动。" }] },
"pattala": { sound: "木质感、明亮而富打击感,音符短促清晰;包布琴槌使音色柔和圆润,八度重叠与快速颤音奏出活泼如涟漪的声音。", range: "24块音条,约三个半八度。", tuning: "每块音条的下侧粘上掺铅屑的蜂蜡块进行微调,调成缅甸七声音阶。", acoustics: "包布琴槌敲击 → 以绳悬挂的竹制或硬木音条 → 下方的船形木槽。", materials: "绳悬的竹制或硬木音条架在弯曲的木箱上;包布琴槌。", making: "由乐器匠人制作,他们把音条切削至目标音高,并雕刻、髹漆装饰的木槽。", usage: "以两支包布琴槌敲击。", role: "旋律,用于室内乐和 hsaing 乐队。", players: "宫廷与职业乐师,也有独奏名家。", skills: "八度重叠、快速跑句与颤音。", scenes: "宫廷室内乐、hsaing 乐队、独奏会。", repertoire: "《玛哈吉塔》古典歌曲、hsaing 乐队乐曲、独奏变奏曲。", origin: "缅甸的木琴,竹制或木制音条架在船形木槽上。", history: "用于宫廷和 hsaing 乐队,有24块以蜂蜡调音的音条,也是独奏乐器。", variants: "有竹制音条和硬木音条两种形制;也制作金属音条的“pattala”。", today: "仍在使用。", techniques: [{ name: "敲击音条", how: "包布琴槌敲击竹制音条,发出柔和空灵的音色。" }, { name: "八度颤音", how: "在两块音条上快速交替敲击以持续一个音。" }] },
"palwei": { sound: "柔和、带气息而甜美的笛音,使用笛膜时带有微微的嗡嗡边缘,以气息揉音和快速装饰音点缀。", range: "约两个八度。", tuning: "七个指孔给出缅甸七声音阶。", acoustics: "气息 → 风道把气流导向窗口边棱 → 竹管空气柱。", materials: "竹子,配风道式吹口、七个指孔和一个笛膜孔。", making: "由演奏者与民间制作者取竹制成,以木块形成风道。", usage: "竖持,经风道吹奏。", role: "旋律,用于室内乐和合奏。", players: "职业与民间乐师。", skills: "带装饰的旋律与气息揉音。", scenes: "室内乐、hsaing 乐队、民歌。", repertoire: "与竖琴、木琴合奏的古典室内乐,hsaing 乐队和民歌。", origin: "缅甸的竹制哨笛。", history: "在室内乐中为缅甸弯琴(saung gauk)和 pattala 伴奏,也在 hsaing 乐队中演奏;笛膜孔带来嗡嗡的音色。", today: "仍在使用。", techniques: [{ name: "颤音装饰", how: "手指快速拍动,装饰旋律。" }, { name: "超吹", how: "加强气息,升入高八度。" }] },
"pat-waing": { sound: "独一无二的旋律性击鼓:调好音的鼓发出短促、圆润、轰鸣的音,演奏者按压鼓面使音高弯曲,奏出快速跑句和节奏性旋律,时而如雷鸣,时而轻柔翻滚。", range: "21面定音鼓,跨越数个八度,从深沉的低音鼓到小而高的鼓。", tuning: "每面鼓通过在鼓面涂抹米糊与灰的糊料调到调式的某个音;每首乐曲都要重新调音。", acoustics: "手掌击打 → 涂有糊料的定音皮制鼓面 → 悬挂在大型框架中的鼓身。", materials: "木鼓蒙皮鼓面,悬挂在雕刻鎏金的圆形框架内;调音糊。", making: "鼓由专门的匠人制作,悬挂在由木雕匠和鎏金匠雕刻、髹漆并鎏金的精致圆形框架中。", usage: "由坐在圆圈内的乐师用手演奏。", role: "旋律与领奏:pat waing 演奏者带领 hsaing waing 乐队。", players: "职业 hsaing 乐师;领奏者称“saing saya”。", skills: "旋律性击鼓、按压鼓面弯音、快速跑句。", scenes: "hsaing waing 乐队、节庆、戏剧与舞蹈。", repertoire: "用于 zat pwe 戏剧、纳特(nat)精灵仪式、佛塔节庆和舞蹈的音乐。", meaning: "鎏金的框架及其装饰是节庆生活的核心景观。", origin: "缅甸的21面定音鼓围圈,是缅甸音乐所独有的。", history: "hsaing 乐队的领奏者坐在鎏金的鼓圈中演奏旋律,并用米糊为每面鼓调音。", today: "仍活跃于缅甸的仪式与戏剧音乐。", techniques: [{ name: "旋律击法", how: "演奏者用手掌与手指敲击由21面定音鼓组成的圆圈,奏出旋律。" }, { name: "闷击", how: "手掌留在鼓面上,发出短促干燥的音。" }, { name: "滚奏", how: "在一面鼓上快速连击形成滚奏。" }] },
"kyi-waing": { sound: "清澈、如钟般响亮的锣音,包布琴槌带来柔和的起音和悠长闪烁的余音,以快速的旋律型演奏。", range: "约21面锣,跨越约三个八度。", tuning: "每面锣通过在其下侧添加或刮除掺铅屑的蜂蜡来调音。", acoustics: "包布琴槌敲击 → 悬于绳上的青铜锣凸起的锣脐 → 向外辐射。", materials: "装在装饰的圆形木框中的青铜凸脐锣;包布琴槌。", making: "青铜锣由锣匠铸造并锤打,圆形框架由木匠雕刻并装饰。", usage: "坐在圆圈内以两支琴槌演奏。", role: "旋律,对 hsaing 的主旋律加以润饰。", players: "职业 hsaing 乐师。", skills: "旋律型与八度重叠。", scenes: "hsaing waing 乐队、节庆与戏剧。", repertoire: "用于节庆、戏剧与舞蹈的 hsaing waing 音乐。", origin: "缅甸的定音凸脐锣围圈,是 hsaing 乐队的一部分。", history: "与泰国和柬埔寨的锣圈相关,与鼓圈一同演奏旋律型。", today: "仍在使用。", techniques: [{ name: "敲锣", how: "包布槌敲击锣圈的锣脐,发出明亮的响声。" }, { name: "止音", how: "敲击后触按锣面,使余音停止。" }] },
"maung": { sound: "深沉、圆润、嗡鸣的锣声,缓缓绽放又渐渐消退;maung zaing 锣排在旋律型中听来更轻、更似钟声。", range: "大型单面 maung 低沉;maung zaing 跨越约两个八度。", acoustics: "包布琴槌敲击 → 青铜锣的中央锣脐 → 振动并向外辐射。", materials: "青铜凸脐锣,maung zaing 装在木框中;包布琴槌。", making: "由锣匠铸造并锤打,尤以曼德勒一带著称。", usage: "用包布琴槌敲击锣脐。", role: "节奏与结构(单面锣)和旋律(锣排)。", players: "hsaing 乐队乐师和寺庙乐师。", skills: "标示周期、在锣排上奏旋律型。", scenes: "hsaing waing、寺庙节庆、仪式。", repertoire: "hsaing waing、寺庙节庆与仪式。", origin: "缅甸的凸脐锣,可单独演奏,或装入框架成为“maung zaing”锣排。", history: "大型单面 maung 在 hsaing 乐队中打拍;装在长方形框架中的18至19面锣的 maung zaing 演奏旋律。", variants: "各种大小的单面悬挂 maung,以及装框的 maung zaing。", today: "仍在使用。", techniques: [{ name: "敲锣", how: "包布槌敲击锣脐,发出深沉的嗡鸣。" }] },
"mi-gyaung": { sound: "轻柔的金属质拨弦音色,起音带弹跳感、衰减短促,以颤音拨奏和高品上的滑音增添生气。", acoustics: "拨片拨弦 → 琴弦按在凸起的品上 → 中空雕刻琴身上的琴码。", materials: "雕成鳄鱼形的中空木制琴身、凸起品上的三根弦。", making: "以整块木头雕成鳄鱼形并髹漆。", usage: "平放于地,用拨片弹拨,左手按品。", role: "室内乐合奏中的旋律。", players: "过去为宫廷乐师;今天为复兴表演者。", skills: "带颤音和滑音的拨奏旋律。", scenes: "孟族与缅甸宫廷室内乐、复兴乐队。", repertoire: "孟族与缅甸古典室内乐。", origin: "孟族和缅人的鳄鱼形有品齐特琴,与高棉的 krapeu 和泰国的 jakhe 相关。", finds: "鳄鱼形齐特琴见于孟族传统,早期缅甸亦有关于“鳄鱼”齐特琴的记载。", history: "见于孟族宫廷和蒲甘时代,几近消失,20世纪得到复兴。", today: "罕见;20世纪得到复兴。", techniques: [{ name: "按音", how: "把弦按在凸起的品上拨奏,发出弹跳的音色。" }, { name: "滑音", how: "手指在品间滑动使音弯曲。" }] },
"roneat-ek": { sound: "明亮、木质感而活泼,音符短促清脆;硬槌带来锐利响亮的边缘,适合响亮的宫廷音乐,包布槌则较柔和,快速的八度跑句与颤音在乐队之上闪烁。", range: "21块音条,约三个八度。", tuning: "音条下侧加入蜡与铅的混合物来调音;演奏近乎等分的七声高棉音阶。", acoustics: "琴槌敲击 → 以绳悬挂的竹制或硬木音条 → 船形木制共鸣箱。", materials: "绳悬的21块竹制或硬木音条架在弯曲的木箱上;硬头或包布头的琴槌。", making: "由专门的匠人制作,他们切削音条并雕刻船形底座。", usage: "以两支琴槌敲击,多为八度。", role: "旋律:领奏 pinpeat,对 kong vong 保持的核心旋律加以变化。", players: "宫廷与寺庙乐师,今天在金边皇家美术大学受训。", skills: "八度演奏、快速颤音及对核心旋律的变奏。", scenes: "王室宫廷舞蹈、寺庙仪式、皮影戏。", repertoire: "用于皇家芭蕾、寺庙仪式和 sbek thom 皮影戏的 pinpeat 音乐。", notation: "口传教学;没有传统记谱。", origin: "pinpeat 乐队的高音高棉木琴,下有船形共鸣箱。", history: "pinpeat 音乐可追溯到吴哥时代的寺庙浮雕;roneat ek 以旋律的快速润饰领奏乐队。", today: "仍在使用;pinpeat 所伴奏的柬埔寨皇家芭蕾和 Sbek Thom 皆被联合国教科文组织列入名录。", techniques: [{ name: "八度击法", how: "双手击打相隔八度的音条,形成明亮的双重线条。" }, { name: "颤音", how: "在慢曲中快速交替敲击以持续一个音。" }] },
"roneat-thung": { sound: "圆润、空灵,比 roneat ek 更低,以柔和的包布槌敲击;其放松的、切分的反拍乐句为明亮的上声部木琴提供了温暖而跳跃的平衡。", range: "16块音条,比 roneat ek 低约两个八度。", tuning: "音条下侧用蜡与铅调音,调成七声高棉音阶。", acoustics: "包布琴槌敲击 → 绳悬的硬木或竹制音条 → 长方形木箱共鸣体。", materials: "长方形木箱上的16块竹制或硬木音条;包布琴槌。", making: "由与 roneat ek 相同的专门匠人制作。", usage: "以两支包布琴槌敲击。", role: "pinpeat 低音区的对旋律。", players: "宫廷与寺庙乐师。", skills: "切分的反拍对旋律。", scenes: "宫廷与寺庙的 pinpeat 乐队。", repertoire: "用于宫廷舞蹈、寺庙仪式和皮影戏的 pinpeat 音乐。", origin: "pinpeat 的低音高棉木琴,带箱形共鸣体。", history: "演奏比 roneat ek 更缓慢、带切分的对应声部。", today: "仍在使用。", techniques: [{ name: "敲击音条", how: "包布琴槌敲击竹制音条,发出低沉圆润的敲击声。" }, { name: "切分击法", how: "反拍的、俏皮的敲击围绕旋律穿插。" }] },
"sralai": { sound: "响亮、尖锐、带鼻音和嗡鸣的簧片音色,借循环换气不间断地吹奏,蜿蜒的滑音和密集的装饰音在木琴和锣之上交织。", tuning: "六个指孔;音高靠唇压和半按音孔塑造,以符合高棉音阶。", acoustics: "气息 → 以四层棕榈叶制成的簧片 → 鼓胀的、大致圆柱形的木制管膛。", materials: "六孔的硬木或象牙管身,四层棕榈叶制成的簧片。", making: "管身以硬木车制,簧片由演奏者用棕榈叶剪裁并系扎。", usage: "鼓起腮帮,以循环换气演奏。", role: "旋律:pinpeat 的主奏管乐器。", players: "宫廷与寺庙乐师。", skills: "循环换气、带装饰的旋律。", scenes: "王室与寺庙典礼、宫廷舞蹈、葬礼。", repertoire: "用于王室典礼、宫廷舞蹈、寺庙仪式和葬礼的 pinpeat 音乐。", origin: "pinpeat 乐队中带鼓胀管身的高棉四层簧双簧管。", history: "与泰国的 pi nai 相关,承担宫廷与仪式音乐的主旋律。", variants: "高音的 sralai touch 和较低的 sralai thom;泰国的 pi nai 和 pi nok 是近亲。", today: "仍在使用。", techniques: [{ name: "循环换气", how: "储存在腮中的气息使声音不间断。" }, { name: "滑音", how: "唇压使音高弯曲。" }] },
"tro": { sound: "甜美、略带鼻音而纤细的弓弦音色,亲切而不响亮,带有滑音和轻柔的揉弦;低音 tro 听来更暗、更空。", range: "约两个八度。", tuning: "两根弦通常相隔五度定弦。", acoustics: "穿插在两弦之间的马尾弓 → 两根弦 → 共鸣体上皮膜或木膜上的琴码。", materials: "椰壳、木头或象牙共鸣体配皮或木面,两根弦,穿过弦间的弓。", making: "民间和专门的制作者用椰壳、木头或象牙做共鸣体,装上硬木琴颈和弦轴。", usage: "竖持于膝上,在两弦之间拉奏。", role: "旋律,用于 mahori 和婚礼乐队。", players: "民间、婚礼与宫廷乐师。", skills: "装饰音与滑音;持续音伴奏。", scenes: "mahori 与婚礼音乐、宫廷乐队。", repertoire: "mahori 音乐、“phleng kar”婚礼音乐和民歌。", origin: "高棉的双弦提琴,有几种类型,如“tro sau”、“tro ou”和“tro khmer”。", history: "与中国的胡琴和泰国的 so 相关,带领“mahori”和婚礼乐队。", variants: "高音的 tro sau toch、较低的 tro sau thom、椰壳琴身的 tro ou,以及三弦的 tro khmer。", today: "仍在使用。", uncertain: "所给出的霍恩博斯特尔—萨克斯分类号针对管形琴身的 tro sau;椰壳琴身的 tro ou 是尖柱弓弦鲁特琴(321.311-71)。", techniques: [{ name: "滑音", how: "手指沿琴弦在音与音之间滑动。" }, { name: "揉弦", how: "摇动手指使音微微颤动。" }] },
"krapeu": { sound: "明亮、弹跳、略带嗡鸣的拨弦音色,金属质起音强烈;颤音拨奏形成持续而闪烁的线条。", acoustics: "拨片拨弦 → 琴弦按在高高凸起的品上 → 中空木身上的琴码。", materials: "木制琴身、三根弦(丝弦或尼龙弦与金属弦)、凸起的品。", making: "中空琴身以硬木雕成并加以装饰,有时仍保留鳄鱼的形状。", usage: "平放,食指戴拨片弹拨。", role: "旋律。", players: "宫廷、婚礼与民间乐师。", skills: "颤音与带装饰的旋律。", scenes: "mahori 乐队、婚礼、宫廷娱乐。", repertoire: "mahori 乐队音乐与婚礼音乐。", origin: "高棉的鳄鱼形有品齐特琴,在吴哥时代的浮雕中呈现为风格化的鳄鱼。", finds: "鳄鱼形齐特琴出现在吴哥时代的寺庙浮雕上。", history: "用于“mahori”和婚礼乐队。", variants: "泰国的 jakhe 与缅甸的 mi gyaung 与之关系密切。", today: "仍在使用,但不如提琴和木琴常见。", techniques: [{ name: "颤音", how: "拨片快速来回拨动以持续一个音。" }, { name: "按音", how: "在高品上按弦以升高音高。" }] },
"chapei": { sound: "干爽、利落、略带弹跳的音色,衰减短促,以有力的乐句奏于歌者唱句之间与之下。", tuning: "两组双弦,通常相隔四度定弦。", acoustics: "拨片拨弦 → 成对的琴弦按在高品上 → 琴身木制面板上的琴码。", materials: "木制琴身、带高品的长琴颈、两组双弦。", making: "由工匠以硬木制成,长琴颈雕成弯曲的琴首。", usage: "歌者即兴演唱时用拨片弹拨。", role: "伴奏:支撑歌者自己的即兴诗句。", players: "自弹自唱的歌者,常为流浪或盲人大师,如孔奈(Kong Nay)。", skills: "带装饰的拨弦线条与即兴诗句。", scenes: "说唱与诙谐歌曲、婚礼、典礼。", repertoire: "即兴叙事歌、诙谐歌与劝世歌、婚礼歌以及诗句形式的佛教训诲。", origin: "高棉带高品的长颈鲁特琴,即“chapei dang veng”。", history: "大师们在它的伴奏下即兴演唱机智或劝世的诗句;Chapei 被联合国教科文组织列为柬埔寨亟需保护的非物质文化遗产。", today: "濒危;Chapei Dang Veng 于2016年被联合国教科文组织列入亟需保护的非物质文化遗产名录。", techniques: [{ name: "拨弦", how: "拨片在高品上拨动琴弦,发出弹跳的音色。" }, { name: "滑音", how: "手指沿琴颈在品间滑动。" }, { name: "扫弦", how: "拨片扫过两组弦,作为节奏性的标点。" }] },
"khloy": { sound: "柔和、空灵、甜美的笛音,有时因笛膜而带有轻微嗡鸣,以气息揉音和快速颤音演奏。", range: "约两个八度。", tuning: "通常有七个指孔和一个拇指孔,制成多种尺寸以适应乐队的音高。", acoustics: "气息 → 风道把气流导向边棱 → 竹管空气柱。", materials: "竹子,配风道式吹口和指孔,有时带笛膜孔。", making: "由演奏者和乡村制作者取竹制成。", usage: "竖持,经风道吹奏。", role: "旋律。", players: "民间与乐队乐师。", skills: "装饰音、颤音和气息揉音。", scenes: "mahori 乐队、婚礼、乡村生活。", repertoire: "mahori 与婚礼乐队、民间曲调。", origin: "高棉的竹制哨笛。", history: "用于 mahori 与婚礼乐队以及民间音乐。", today: "仍在使用。", techniques: [{ name: "颤音装饰", how: "手指快速拍动,装饰旋律。" }, { name: "超吹", how: "加强气息,升入高八度。" }] },
"kong-vong": { sound: "响亮、温暖的青铜音色,起音柔和,余音悠长闪烁,以稳定的八度演奏;低音的 kong vong thom 发出深沉庄重的嗡鸣,kong vong toch 则更明亮、更快速地闪烁。", range: "十六面锣,略超过两个八度。", tuning: "每面锣在锣脐下侧用掺铅的蜂蜡调成高棉七声音阶。", acoustics: "包布琴槌敲击 → 悬于绳上的青铜锣的锣脐 → 向外辐射。", materials: "弯曲藤架上的十六面青铜凸脐锣;包布琴槌。", making: "锣由锣匠铸造并锤打;藤架由乐器匠人制作。", usage: "坐在圆圈内以两支琴槌演奏。", role: "核心旋律:保持其他乐器加以变奏的主旋律。", players: "宫廷与寺庙乐师。", skills: "八度的核心旋律、止音。", scenes: "宫廷舞蹈、寺庙仪式、皮影戏中的 pinpeat。", repertoire: "用于皇家芭蕾舞、寺庙仪式和皮影戏的 pinpeat 音乐。", origin: "高棉的定音凸脐锣圈(“kong”意为锣),有高音的“kong vong toch”和低音的“kong vong thom”两种形制。", finds: "吴哥时代的寺庙浮雕中描绘有锣圈。", history: "见于吴哥浮雕,保持 pinpeat 乐队的核心旋律。", variants: "较低的 kong vong thom 和较高的 kong vong toch。", today: "仍在使用。", techniques: [{ name: "敲锣", how: "包布槌敲击锣脐,奏出响亮的旋律。" }, { name: "止音", how: "触按锣面使余音停止。" }] },
"skor-thom": { sound: "深沉、轰鸣的闷响,钉在鼓框上的皮面带来短促的余响;两面鼓音高不同,一对鼓发出一低一略高的轰鸣。滚奏渐涨为暗沉的隆隆声,传遍寺庙庭院。", range: "无固定音高,深沉;一对鼓大致相隔一个全音或四度。", acoustics: "鼓槌击打 → 钉固的皮制鼓面 → 木制桶形鼓身。", materials: "钉上皮面的木制桶形鼓、鼓槌。", making: "鼓桶由整根树干掏空,皮面湿润时绷紧,以木钉或金属钉固定;在某些传统中,鼓面涂以米糊与灰的糊料来调音。", usage: "斜置于架上,用鼓槌敲击。", role: "节奏:与小钹(ឈិង chhing)和锣一起标示节拍周期的各击点。", players: "隶属于寺庙和宫廷 pinpeat 乐队的男性职业乐师。", skills: "标示周期的节奏与滚奏。", scenes: "寺庙与宫廷典礼、葬礼中的 pinpeat。", repertoire: "用于典礼、皇家芭蕾(របាំព្រះរាជទ្រព្យ)和面具戏(ល្ខោនខោល lkhaon khol)的 pinpeat 曲目。", origin: "高棉 pinpeat 的一对大型桶形鼓。", finds: "12世纪吴哥窟与巴戎寺的浮雕中出现架在支架上的大型桶形鼓。", history: "见于吴哥浮雕,保持宫廷与寺庙音乐的节奏周期。", variants: "标准为一对;泰国的กลองทัด(klong)是同一类型。", today: "仍活跃于 pinpeat 乐队;柬埔寨皇家芭蕾被联合国教科文组织列入名录(2003/2008年)。", techniques: [{ name: "鼓槌击法", how: "鼓槌敲击成对的桶形鼓,发出深沉的轰鸣。" }, { name: "滚奏", how: "快速连击,如滚滚雷声。" }] },
"serunai": { sound: "响亮、尖锐、带鼻音和簧片嗡鸣,借循环换气不停歇地吹奏;旋律中充满快速的回旋音与滑音。", range: "约一个半八度。", tuning: "依地方旋律调式演奏,而非固定的平均律音阶;音高随乐器与簧片而异。", acoustics: "气息 → 四层(折叠棕榈叶)簧片 → 带外翻喇叭口的锥形管膛。", materials: "锥形木身、棕榈叶簧片、唇盘、外翻的喇叭口。", making: "由当地工匠以硬木车制,配金属或木制喇叭口;演奏者自己制作并修整叶簧。", usage: "以循环换气吹奏,嘴唇抵在唇盘上。", role: "旋律:诺巴特(nobat)以及 silat 和皮影戏乐队中唯一的旋律声部。", players: "宫廷中世袭的诺巴特乐师;为 silat 和皮影戏服务的乡村职业乐师。", skills: "循环换气、带装饰的旋律。", scenes: "诺巴特王室典礼、silat、皮影戏(wayang kulit)、婚礼。", repertoire: "诺巴特仪式乐曲、silat 伴奏(gendang silat)、吉兰丹皮影戏、玛雍(mak yong)。", origin: "马来唢呐,属经波斯和印度接触传来的 surnay 家族。", history: "它引领王室“诺巴特”乐队,并为“silat”武术和“wayang kulit”皮影戏伴奏。", variants: "有不同大小的 serunai;印度尼西亚的 sarunai 与米南加保的 sarunai 是近亲。", today: "仍在使用;可在其中听到它的玛雍戏剧被联合国教科文组织列入名录(2008年)。", techniques: [{ name: "循环换气", how: "储存在腮中的气息使音色不间断。" }, { name: "滑音", how: "唇压使音高弯曲。" }] },
"nafiri": { sound: "明亮、铜管般、穿透力强的长音,渐强并保持,常由 serunai 应答;几乎没有旋律。", range: "一两个自然音。", acoustics: "颤动的嘴唇 → 长直管 → 外翻的喇叭口;没有指孔或活塞。", materials: "带外翻喇叭口的银制或黄铜管。", making: "由宫廷金属匠人用银片或黄铜片锤打并焊接而成。", usage: "用颤动的嘴唇吹奏,保持长音。", role: "信号:标示王者莅临的仪式性长音。", players: "侍奉苏丹的世袭诺巴特乐师(orang kalur)。", skills: "持续的单音号声。", scenes: "王室登基与国家典礼上的诺巴特。", repertoire: "用于王室登基、开斋和王室葬礼的诺巴特乐曲。", meaning: "作为诺巴特御用乐器的一部分,它体现统治者的威权(daulat),只在其面前或奉其命令时才演奏。", origin: "马来王室“诺巴特”的长银号,源自波斯语和阿拉伯语的 nafīr。", history: "随伊斯兰宫廷文化传入,仅在统治者登基等王室典礼上鸣响。", variants: "每个诺巴特(吉打、霹雳、登嘉楼、雪兰莪、文莱)各保存一支 nafiri。", today: "仅存于尚存的王室诺巴特乐队之中。", techniques: [{ name: "长吹", how: "在号的自然音上持续的号声。" }, { name: "超吹", how: "收紧嘴唇跳到更高的分音。" }] },
"nengkara": { sound: "干燥、尖锐的脆响,余音短促,以快速重复的节奏型演奏,位于更低沉的 gendang 鼓之上。", range: "无固定音高,中高音区。", acoustics: "鼓槌击打 → 皮制鼓面 → 封闭的碗形(釜形)鼓身。", materials: "金属或木制鼓碗配皮制鼓面;鼓槌。", making: "由宫廷工匠制作;因这面鼓是御用乐器,换皮时要以仪式般的郑重对待。", usage: "坐着用鼓槌敲击。", role: "节奏:诺巴特的计时鼓,与 gendang nobat 相互交织。", players: "世袭的诺巴特乐师。", skills: "与 gendang 配合的仪式性节奏型。", scenes: "王室登基、开斋节(Hari Raya)与国家典礼上的诺巴特。", repertoire: "诺巴特仪式乐曲,如《Raja Berangkat》和《Nobat Tabal》。", meaning: "与其他诺巴特乐器一起作为神圣的御用物品保存;不可随意演奏。", origin: "马来王室“诺巴特”的釜鼓,源自波斯的 naqqara。", history: "它与 gendang nobat 鼓一起构成马来苏丹国的神圣御用乐器,只由世袭乐师演奏。", variants: "吉打、登嘉楼、霹雳、雪兰莪和文莱的诺巴特乐队各有一面。", today: "仅存于王室诺巴特乐队之中。", techniques: [{ name: "鼓槌击法", how: "鼓槌敲击釜鼓,发出深沉的轰鸣。" }, { name: "滚奏", how: "快速连击,如滚滚雷声。" }] },
"gambus": { sound: "温暖、干爽、延音短促的弹拨声;蒙皮面板的形制更富打击感、近似班卓琴,乌德式的则更圆润、余音更长。", range: "约两个八度。", tuning: "成对的弦组按乌德琴的方式相隔四度定弦;旋律采用适应马来歌曲的类木卡姆(maqam)调式。", acoustics: "拨片拨弦 → 肠弦或尼龙弦 → 雕刻琴碗上的皮面或木面板。", materials: "掏空的木制琴身,有时配皮面板,肠弦或尼龙弦,拨片。", making: "蒙皮面板的类型以整块木头雕成,下半部面板用山羊皮或蜥蜴皮;乌德式的则以木条拼成。", usage: "像乌德琴那样持握,用拨片弹拨。", role: "旋律:与 marwas 手鼓一起带领 zapin 乐队。", players: "马来人及哈德拉毛后裔群体的男性民间乐师。", skills: "带装饰的类似“塔克西姆”(taqsim)的引子、为 zapin 作节奏性扫弦。", scenes: "zapin 舞蹈、加扎尔(ghazal)、婚礼与伊斯兰节庆。", repertoire: "zapin 舞蹈、马来加扎尔、纳希德(nasyid)以及受阿拉伯影响的歌曲(lagu gambus)。", origin: "马来世界的梨形拨弦鲁特琴,源自也门的 qanbus 和哈德拉毛商人带来的阿拉伯乌德琴。", history: "成为马来“zapin”舞蹈音乐和“加扎尔”的核心,有蒙皮面板和乌德式两种形制。", variants: "gambus Melayu(蒙皮面板、雕成)和 gambus Hadhramaut(乌德式);沙巴、文莱和苏门答腊有相关的鲁特琴。", today: "仍活跃于 zapin 与加扎尔,尤其在柔佛。", techniques: [{ name: "拨弦", how: "拨片拨动成对的弦,发出深沉圆润的音色。" }, { name: "颤音", how: "快速交替拨奏以持续一个音。" }, { name: "滑音", how: "手指沿无品琴颈滑动。" }] },
"kecapi": { sound: "轻盈、明亮、响亮的拨弦音色,衰减迅速;齐特琴形制奏出一串串闪烁的五声音型。", range: "较大的齐特琴约两到三个八度。", tuning: "巽他人的 kacapi 通过移动琴码重新定音,调成佩洛格(pelog)、索罗格(sorog,madenda)和斯连德罗(salendro)等五声调式。", acoustics: "手指拨弦 → 可动琴码上的金属弦或尼龙弦 → 船形或箱形共鸣体。", materials: "配金属弦或尼龙弦的木制琴身。", making: "由专门的匠人以菠萝蜜木或类似木材雕成;巽他的大型 kacapi indung 为船形。", usage: "平放,用手指弹拨。", role: "和声与旋律:为吟唱的诗歌伴奏,由 suling 笛承担曲调。", players: "民间与宫廷乐师;在巽他,既有职业乐队演奏者,也有歌者的伴奏者。", skills: "相互交织的音型和带装饰的旋律。", scenes: "吟唱的诗歌、宫廷娱乐、稻谷收获仪式。", repertoire: "巽他的 tembang Sunda Cianjuran 与 kacapi suling;马来吟唱诗歌。", origin: "马来和印度尼西亚世界的一种齐特琴或鲁特琴的名称,最知名的是巽他人的船形齐特琴和马来宫廷的拨弦乐器。", history: "kecapi 齐特琴为吟唱的诗歌伴奏;在马来语中,这个名称涵盖数种拨弦乐器。", variants: "kacapi indung(大型船形齐特琴)、kacapi rincik(小型)、kacapi siter;苏门答腊和苏拉威西的船形鲁特琴也用这个名称。", uncertain: "这个名称在整个马来世界涵盖几种不同的齐特琴和鲁特琴,因此细节取决于所指的是哪一种乐器。", techniques: [{ name: "拨弦", how: "手指拨动齐特琴的弦,发出明亮的涟漪声。" }, { name: "止音", how: "用手按住琴弦使音变短。" }] },
"saron": { sound: "明亮、铿锵的金属声,起音坚硬,不止音则延音很长;许多萨隆演奏同一旋律线时,发出闪烁的拍音。", range: "约一个八度(佩洛格七块音条,斯连德罗六或七块);demung、saron barung 和 peking 相隔八度。", tuning: "调成加美兰自有的斯连德罗或佩洛格音阶,各套之间不尽相同;音条以锉削调音。", acoustics: "琴槌敲击 → 厚青铜音条 → 中空木槽共鸣体。", materials: "雕刻木槽上的青铜或铁制音条;木制或水牛角琴槌。", making: "音条由加美兰锻匠(empu)用青铜(较廉价的套组用铁)锻打而成,并与整套乐器一起调音。", usage: "一手用槌敲击,另一手按住前一块音条止音。", role: "旋律:演奏加美兰的骨干核心旋律(balungan)。", players: "宫廷和乡村的加美兰乐师;常是最先学的乐器。", skills: "止音、交织的“imbal”音型。", scenes: "宫廷中的加美兰、舞蹈和皮影戏(wayang)。", repertoire: "爪哇的 gendhing;登嘉楼宫廷的马来加美兰(gamelan Melayu)乐曲。", notation: "Kepatihan 数字谱(数字 1–7)记录萨隆所奏的 balungan。", origin: "爪哇与马来加美兰的金属音条琴,厚青铜音条架在共鸣槽上。", history: "萨隆演奏加美兰的核心旋律“balungan”;廖内—彭亨宫廷的马来加美兰也使用它们。", variants: "demung(低音)、saron barung(中音)、saron peking(高音)。", today: "仍在使用;加美兰被联合国教科文组织列入名录(2021年)。", techniques: [{ name: "敲击音条", how: "琴槌敲击青铜音条,发出明亮响亮的音。" }, { name: "止音", how: "敲下一块音条时,左手捏住前一块使其余音停止。" }, { name: "交织(imbal)", how: "两位演奏者交替敲击,形成快速交织的音型。" }] },
"seruling": { sound: "柔和、带气息、空灵的音色,起音轻柔,高音区甜美而略带沙哑;气息揉音和装饰音赋予它歌唱般的质感。", range: "约两个八度。", tuning: "指孔位置依地方传统而定,给出五声或近似自然音阶的音阶。", acoustics: "气息 → 气流冲击边棱(侧孔,或带环的风道)→ 竹管。", materials: "竹子,开六个指孔。", making: "取薄壁竹子,烙出或钻出孔洞,常由演奏者自己制作。", usage: "横吹吹孔,或经风道吹奏。", role: "旋律:在拨弦和鼓的伴奏之上担任主奏或装饰线条。", players: "民间乐师、牧人和宫廷乐队演奏者。", skills: "装饰音与气息揉音。", scenes: "民歌、马来加美兰、婚礼。", repertoire: "马来民歌、马来加美兰、印度尼西亚的 kacapi suling。", origin: "马来世界的竹笛,有横吹和竖吹两种形制。", history: "用于马来民间音乐和宫廷音乐,印度尼西亚的 suling 是其近亲。", variants: "横吹和竖吹形制;印度尼西亚的 suling 带藤环风道。", today: "仍在使用。", uncertain: "这个名称既涵盖横吹笛也涵盖哨笛,因此声学原理和霍恩博斯特尔—萨克斯分类号(所给为横吹形制)会有所不同。", techniques: [{ name: "颤音装饰", how: "手指快速拍动,装饰旋律。" }, { name: "超吹", how: "加强气息,升入高八度。" }] },
"gong-agung": { sound: "深沉、温暖、嗡鸣的轰响,击后绽开,并在数秒的衰减中脉动。", range: "低音,基音有固定音高,与乐队定音一致。", tuning: "通过锤打调成乐队的音阶;其缓慢的脉动(ombak)备受珍视。", acoustics: "包布槌敲击 → 带锣脐、边缘下折的青铜板 → 周围的自由空气。", materials: "悬于框架的青铜凸脐锣;包布槌。", making: "由锣匠用青铜反复加热锤打锻成;最受尊崇的锻坊位于中爪哇和登嘉楼。", usage: "用包布槌敲击锣脐,任其鸣响。", role: "结构:标示最大周期(gongan)的结束。", players: "加美兰与诺巴特乐师。", skills: "以深沉的击声标示打击乐分段周期。", scenes: "加美兰、诺巴特、皮影戏、婚礼和典礼。", repertoire: "加美兰、诺巴特、皮影戏、silat 和玛雍音乐。", meaning: "大锣被视为传家宝和声望之物,有时被认为附有灵,并受到供奉。", origin: "马来和印度尼西亚音乐中的大型悬挂凸脐锣;“tetawak”是大锣的马来语名称。", history: "马来世界的锣是青铜制的身份象征物;大锣在加美兰、诺巴特和皮影戏中标示每个周期的结束。", variants: "gong ageng、gong suwukan、kempul;马来的 tetawak。", today: "仍在使用;加美兰被联合国教科文组织列入名录(2021年)。", techniques: [{ name: "敲锣", how: "包布槌敲击锣脐,发出深沉悠长的嗡鸣。" }, { name: "止音", how: "触按锣面使余音停止。" }] },
"dan-bau": { sound: "纯净、似笛的泛音,演奏者将其弯成宽广哀婉的滑音和缓慢的揉音,宛如人声;带扩音的版本延音更长,听来近似特雷门琴。", range: "约三个八度的泛音,经琴杆弯音可更宽。", tuning: "单弦通常定为 C3 或相近的音;音符来自 ½、⅓、¼……处的泛音,中间的音高靠弯动琴杆取得。", acoustics: "手掌触按节点同时拨片拨弦 → 单根钢弦(泛音)→ 长箱形共鸣体;柔性琴杆改变张力。", materials: "长条木制或竹制音箱、一根钢弦、带葫芦的水牛角或竹制柔性琴杆、薄拨片。", making: "由专门的制琴师制作,主要集中在河内一带;音箱为木制或竹制,琴杆为水牛角,现代的则装有拾音器。", usage: "平放;右手用拨片拨泛音,同时以掌侧触弦,左手弯动琴杆。", role: "旋律:在拨弦和拉弦乐器之上的独奏声部。", players: "过去为盲人流浪歌者;如今是受过专业训练的音乐学院独奏家,男女皆有。", skills: "只奏泛音、弯动琴杆产生宽广的滑音和揉音、如人声的装饰音。", scenes: "民歌、歌筹(ca trù)与嘲剧(chèo)、街头卖唱“hát xẩm”、现代独奏。", repertoire: "hát xẩm 街头歌曲、北部民歌、《望古》(Vọng cổ)改编曲,以及《Tiếng đàn bầu》等现代独奏曲。", meaning: "越南有一句俗语告诫女孩不要听独弦琴,因为它的声音太过迷人。", origin: "京族(越人)的独弦琴,单弦由柔性琴杆弯动。", history: "18世纪才有确切记载,由盲人街头歌者演奏,20世纪成为越南音乐的象征,后来加装电拾音器。", variants: "有竹管形和木箱形两种;广西的京族演奏同一种乐器(独弦琴)。", today: "仍流传,且是标志性乐器;hát xẩm 正在复兴。", uncertain: "18世纪以前的起源没有文献记载,带张力杆的单弦琴在霍恩博斯特尔—萨克斯分类中的位置,各家说法不一。", techniques: [{ name: "泛音", how: "手侧触按节点,同时拨片拨弦,发出清晰的泛音。" }, { name: "弯杆", how: "推拉柔性琴杆使音高平滑弯曲,如人声。" }, { name: "揉音", how: "摇动琴杆使音微微颤动。" }] },
"dan-tranh": { sound: "明亮、清脆、竖琴般的拨弦音色,衰减清晰,由琴码左侧的按压弯音和摇曳的揉音着色;快速颤音带来银色的延音。", range: "约三个八度(16弦),现代19至22弦型号更宽。", tuning: "通过滑动琴码调成五声音阶;按压产生北调(Bắc,明亮)与南调(Nam,忧伤,带弯音的 oán 音)等调式。", acoustics: "指甲拨片拨弦 → 可动琴码上的钢弦 → 长条中空木箱。", materials: "泡桐或其他木制琴身、钢弦、可动琴码、指甲拨片。", making: "由制琴师以泡桐或其他轻木制成,配硬木框架和可动琴码。", usage: "平放,用拨片弹拨;左手在琴码之外按弦。", role: "室内乐与宫廷乐队中的旋律与装饰。", players: "过去为宫廷乐师;今天为业余室内乐演奏者和音乐学院独奏家,多为女性。", skills: "按压弯音与揉音、颤音和滑奏。", scenes: "顺化宫廷音乐、才子乐(đờn ca tài tử)、民间乐队。", repertoire: "才子乐曲目,如《Lưu thủy》《Nam ai》;雅乐宫廷音乐;现代音乐会作品。", notation: "传统上口传耳授,并用源自“工尺”的 hò xự xang xê cống 唱名。", origin: "越南带可动琴码的齐特琴,源自中国的筝,自陈朝起用于宫廷。", history: "有16根弦(现达22根),用于宫廷、室内乐“才子乐”和民间音乐。", variants: "传统16弦,现代17至22弦。", today: "仍流传;才子乐(2013年)和雅乐(2003/2008年)被联合国教科文组织列入名录。", techniques: [{ name: "按弯音", how: "左手在琴码之外按弦使音高弯曲。" }, { name: "揉音", how: "摇动被按住的弦使音微微颤动。" }, { name: "滑奏", how: "手指扫过琴弦,形成涟漪般的跑句。" }, { name: "颤音", how: "快速来回拨弦以持续一个音。" }] },
"dan-nhi": { sound: "纤细、明亮、带鼻音、略显哀怨的弓弦音色,非常接近人声;滑音和快速揉弦使它如哭如诉。", range: "约两个半八度。", tuning: "两根弦相隔五度(有时四度)定弦,音高依歌者而定。", acoustics: "穿插在两弦之间的马尾弓 → 两根弦 → 小型蒙皮筒形共鸣体。", materials: "蒙蟒皮的小型硬木或竹制共鸣体、长琴颈、两根弦、穿过弦间的弓。", making: "由乐器匠人以硬木或竹子制成,蒙蛇皮面。", usage: "竖持于膝上,在两弦之间拉奏。", role: "旋律:与声乐线条重叠并加以润饰。", players: "戏剧乐师、宫廷与民间演奏者。", skills: "滑音、揉弦和如人声的装饰音。", scenes: "嘲剧(chèo)与改良剧(cải lương)、宫廷音乐、民间乐队。", repertoire: "嘲剧与改良剧、召文(chầu văn)、雅乐、民间乐队。", origin: "越南的双弦提琴,与中国的胡琴家族相关。", history: "京族用于宫廷、戏剧和民间乐队,其较大的近亲是 đàn hồ。", variants: "đàn nhị(高音)、đàn hồ(低音);南方的 đàn cò 是同一种乐器。", today: "仍在使用。", techniques: [{ name: "滑音", how: "手指沿琴弦在音与音之间滑动。" }, { name: "揉弦", how: "按压与放松琴弦使音微微颤动。" }, { name: "拨奏", how: "用手指拨弦而不用弓。" }] },
"dan-ho": { sound: "深沉、圆润、浑厚的弓弦音色,带有柔和、略显空洞的鼻音色彩,温暖而非明亮。", range: "约两个八度,比 đàn nhị 低约一个八度。", tuning: "两根弦相隔五度。", acoustics: "穿插在两弦之间的马尾弓 → 两根弦 → 大型蒙皮共鸣体。", materials: "较大的木制或椰壳共鸣体配皮面、两根弦、弓。", making: "由乐器匠人制作,琴身为比 đàn nhị 更大的木制或椰壳琴身。", usage: "竖持,在两弦之间拉奏。", role: "提琴声部中的低音与次中音支撑。", players: "合奏与乐团乐师。", skills: "持续的低音线条、滑音。", scenes: "南部室内乐、戏剧、民族乐团。", repertoire: "南部室内乐、改良剧、现代民族乐团作品。", origin: "音高较低、琴身较大的越南双弦提琴。", history: "用于越南南部音乐和现代民族乐团,是提琴家族的低音声部。", variants: "现代乐团中有中音和低音两种尺寸。", today: "仍在使用。", techniques: [{ name: "滑音", how: "手指沿琴弦在音与音之间滑动。" }, { name: "揉弦", how: "摇动手指使深沉的音微微颤动。" }] },
"dan-gao": { sound: "温暖、深沉、沙哑的弓弦音色,起音柔和,比 đàn nhị 更闷、更有木质感。", range: "约两个八度。", tuning: "两根弦相隔五度。", acoustics: "穿插在两弦之间的马尾弓 → 两根弦 → 带木面的椰壳共鸣体。", materials: "蒙木板的椰壳、硬木琴颈、两根弦、弓。", making: "以半个椰壳蒙上薄木板,配硬木琴颈制成。", usage: "竖持,在两弦之间拉奏。", role: "南部乐队中的旋律与支撑。", players: "南部的室内乐与戏剧乐师。", skills: "圆润的滑音与揉弦。", scenes: "才子乐(đờn ca tài tử)、改良剧(cải lương)、葬礼。", repertoire: "才子乐、改良剧、南部葬礼音乐。", origin: "越南南部带椰壳共鸣体的双弦提琴。", history: "与中国的椰胡(椰壳胡琴)相关,为南部乐队增添温暖的低音。", today: "仍在使用,但较不常见。", techniques: [{ name: "滑音", how: "手指沿琴弦在音与音之间滑动。" }] },
"dan-nguyet": { sound: "清澈、明亮、响亮的拨弦音色,延音相当长;在极高的品之间按弦产生弯音和宽幅揉音,听来如人声。", range: "约两个八度。", tuning: "两根弦相隔四度或五度定弦;高品使同一品位可通过压力给出多个音高,用于召文(chầu văn)和才子乐的调式。", acoustics: "拨片拨弦 → 高品上的两根弦 → 圆形木制琴身。", materials: "圆形木制琴身、带高品的长琴颈、两根弦、拨片。", making: "由乐器匠人制作,圆形木制琴身,长琴颈上有8至10个凸起的品。", usage: "横抱于身前,用拨片弹拨。", role: "旋律:召文中的主奏,室内乐中的主要声部。", players: "召文乐师(cung văn)、宫廷乐师、室内乐业余爱好者。", skills: "在高品之间按弦弯音、揉音、装饰音。", scenes: "召文灵媒仪式、宫廷音乐、才子乐。", repertoire: "召文附体音乐、才子乐、雅乐。", origin: "越南的“月琴”,圆形琴身配带高品的长琴颈,与中国的月琴相关。", history: "在宫廷音乐、仪式性的“召文”和南部室内乐中不可或缺。", variants: "在南方称 đàn kìm。", today: "仍在使用;召文所属的“越人信仰母神的实践”被联合国教科文组织列入名录(2016年)。", techniques: [{ name: "按弯音", how: "在高品之间按弦使音高弯曲。" }, { name: "颤音", how: "快速交替拨奏以持续一个音。" }] },
"ty-ba": { sound: "清脆、明亮、富打击感的拨弦音色,衰减迅速,以轮指使之连续;比中国琵琶更柔和温暖。", range: "约三个八度。", tuning: "四根弦按所用调式定音,常为四度和五度。", acoustics: "手指或拨片拨弦 → 凸起品位上的四根弦 → 梨形木制琴身。", materials: "梨形木制琴身、品、四根弦。", making: "由制琴师以木头制成,琴身雕刻并带凸起的品。", usage: "竖持,用手指或拨片弹拨。", role: "室内乐与宫廷乐队中的旋律与装饰。", players: "过去为宫廷乐师;今天为室内乐演奏者。", skills: "轮指与带装饰的旋律。", scenes: "顺化宫廷音乐、室内乐、民歌伴奏。", repertoire: "顺化雅乐、顺化室内歌曲(ca Huế)、民歌伴奏。", origin: "越南的梨形鲁特琴,源自中国的琵琶。", history: "用于李朝与陈朝宫廷以及顺化宫廷音乐,后来进入室内乐和民间乐队。", today: "仍在使用,但不如过去常见。", techniques: [{ name: "轮指", how: "手指快速连续拨弦,形成滚动的延音。" }, { name: "按弯音", how: "在高品之间按弦使音高弯曲。" }, { name: "扫弦", how: "手指扫过所有琴弦,奏出和弦。" }] },
"sao-truc": { sound: "清澈、带气息、空灵的音色,低音区柔和而惆怅,高音区明亮;颤音、滑音和气息揉音使它带有田园气息。", range: "约两个八度。", tuning: "六个指孔给出五声音阶,其他音靠半按音孔取得;竹笛有多种调高。", acoustics: "气息 → 气流冲击吹孔边棱 → 竹管。", materials: "竹子,开一个吹孔和六个指孔。", making: "取薄竹制成,孔洞烙出,由制作者和演奏者自己调音。", usage: "横持,横吹吹孔。", role: "旋律。", players: "乡村乐师、牧人、戏剧乐师和现代独奏家。", skills: "装饰音、颤音和气息揉音。", scenes: "民歌、嘲剧(chèo)、乡村生活。", repertoire: "北部民歌、嘲剧、官贺民歌(quan họ)、现代独奏曲。", meaning: "堤坝上牧童的笛声,是越南乡村的经典意象。", origin: "越南的竹制横笛;竹笛是该地区最古老的乐器之一,可追溯到东山文化时期。", history: "在北部民间音乐中深受喜爱,令人联想起乡村生活和牧童的笛声。", variants: "sáo ngang(横吹)、sáo dọc(竖吹)。", today: "仍在使用。", techniques: [{ name: "滑音", how: "手指滑上或滑离音孔使音高弯曲。" }, { name: "颤音", how: "手指快速拍动,装饰旋律。" }, { name: "超吹", how: "加强气息,升入高八度。" }] },
"ken": { sound: "响亮、明亮、尖锐带鼻音的簧片音色,传遍户外;滑音和快速装饰音使它在葬礼上哀号、在节庆上灿然。", range: "约一个半到两个八度。", tuning: "七或八个指孔;以越南五声调式演奏,带弯音。", acoustics: "气息 → 双簧片 → 锥形木制管膛 → 外翻喇叭口。", materials: "锥形木身、小簧片、葫芦形的木制或金属喇叭口。", making: "由乐器匠人以硬木车制,配铜制或木制喇叭口;演奏者用芦苇或棕榈叶自制簧片。", usage: "在户外大声吹奏,簧片含在口中。", role: "旋律:领奏户外仪式与游行乐队。", players: "职业仪式与葬礼乐师;过去还有宫廷乐师。", skills: "循环换气、滑音与装饰音。", scenes: "宫廷仪式、葬礼、寺庙节庆。", repertoire: "顺化雅乐宫廷音乐、葬礼音乐(nhạc lễ)、寺庙节庆。", origin: "越南的锥形唢呐(kèn bầu、kèn già nam),与中国的唢呐相关。", history: "用于顺化宫廷礼乐以及葬礼和节庆乐队。", variants: "kèn già nam(大型)、kèn bầu(带葫芦形喇叭口)、kèn đám ma(葬礼用)。", today: "仍在使用;雅乐被联合国教科文组织列入名录(2003/2008年)。", techniques: [{ name: "循环换气", how: "储存在腮中的气息使音色不间断。" }, { name: "滑音", how: "唇压使音高弯曲。" }] },
"chuong": { sound: "深沉、幽暗、嗡鸣的轰响,木撞杆带来柔和的起音和非常悠长而脉动的余音;小钟则发出较明亮的响声。", range: "低音,基音强劲,分音缓慢拍动。", acoustics: "木梁撞击 → 厚重的铸青铜钟,自外侧敲击。", materials: "铸青铜;木梁或木杆。", making: "由铸钟作坊用泥范以青铜铸成,常带铭文和龙形悬钮。", usage: "用木撞杆从外侧敲击。", role: "信号与仪式:标示时辰和佛教法事的各个阶段。", players: "僧人与寺院看守人。", skills: "留出间隔的敲击,让余音充分延续。", scenes: "佛教寺院、仪式、节庆。", repertoire: "寺院的晨钟暮鼓法事与诵经。", meaning: "人们相信钟声能唤醒众生脱离苦难,并传递祈祷。", origin: "越南的寺钟,属东亚佛教钟的类型。", finds: "公元798年的清梅钟(Thanh Mai)是越南已知最古老的有明确年代的青铜钟。", history: "大型青铜钟悬挂于寺院,用木梁从外侧敲击;小钟用于诵经。", variants: "寺院大钟(đại hồng chung)和小型手持或案上钟(chuông gia trì)。", today: "仍在寺院中使用。", techniques: [{ name: "撞钟", how: "木撞杆击钟,发出悠长深沉的响声。" }] },
"trong-cai": { sound: "鼓面发出深沉共鸣的轰响,鼓边则发出尖锐的木击声;滚奏渐强为雷鸣般的轰响。", range: "无固定音高,深沉。", acoustics: "鼓槌击打 → 水牛皮或牛皮鼓面 → 木制桶形鼓身。", materials: "蒙水牛皮或牛皮鼓面的木制桶形鼓。", making: "由乡村制鼓匠制作,尤以河南省的 Đọi Tam 著名;皮面绷在菠萝蜜木或其他木材的鼓桶上,以竹钉固定。", usage: "用鼓槌敲击鼓面和鼓边。", role: "节奏与信号:带领节庆和戏剧乐队。", players: "乡村男子、戏剧鼓手、仪式主持者。", skills: "信号节奏、滚奏、击鼓边。", scenes: "乡村节庆、嘲剧(chèo)、公所(đình)仪式、战事。", repertoire: "嘲剧、节庆击鼓、公所仪式、歌筹(ca trù)的信号(trống chầu)。", meaning: "村鼓象征社群;鼓声召集集会,并宣告战事或洪水。", origin: "越南村落公所“đình”和军队的大型桶形鼓。", history: "曾用来发出村民集会和战争的信号;带领节庆、戏剧与仪式音乐。", variants: "trống cái(大鼓)、trống chầu(歌筹与越剧 tuồng 中评判者的鼓)、trống đế(小鼓)。", today: "仍在使用。", techniques: [{ name: "击鼓面", how: "鼓槌击打鼓面,发出深沉的轰鸣。" }, { name: "击鼓边", how: "鼓槌敲击木制鼓边,发出干脆的咔声。" }, { name: "滚奏", how: "快速连击,如滚滚雷声。" }] },
"khen": { sound: "丰厚、嗡鸣、手风琴般的和弦,伴有连续的持续音,随吹气与吸气的节奏脉动;旋律在持续音之上奔走。", range: "约两个八度(16管的老挝 khaen)。", tuning: "管子调成七声音阶,由此演奏五声调式(lai),如 lai yai、lai noi、lai sutsanaen 和 lai po sai。", acoustics: "气息(吹与吸)→ 金属自由簧片 → 竹管,仅当指孔被按住时才发声。", materials: "装在硬木风箱中的带金属自由簧片的竹管,以蜡封固。", making: "由老挝、泰国东北部和越南高原村落的专门 khaen 匠人制作;簧片由铜银合金锤打而成,以刮削调音。", usage: "双手持握,通过风箱吹气与吸气,手指按住孔。", role: "同时担任和声、持续音与旋律;是 lam 歌唱唯一的伴奏。", players: "多为男性,从乡村演奏者到职业的 mor khaen。", skills: "吹吸连绵不断的发声、持续音与和弦、节奏性的气息型。", scenes: "求偶、乡村节庆、稻作仪式、lam 歌唱。", repertoire: "老挝和伊森(Isan)的 lam 与 mor lam 歌唱;独奏的 lai 调式;苗族和芒族(Mường)的求偶与葬礼音乐。", origin: "竹管排成两列的自由簧口风琴,老挝人、泰人、苗族、芒族等民族演奏;演奏者形象见于东山青铜鼓。", finds: "口风琴演奏者的形象见于公元前最后几个世纪的东山青铜鼓。", history: "最古老的自由簧乐器之一,是后来笙所用自由簧原理的源头;老挝 khaen 音乐被联合国教科文组织列入名录。", variants: "6、8(khaen paet)、7或9对管的 khaen;管子成束的苗族 qeej;芒族 khèn。", today: "仍流传;老挝 khaen 音乐被联合国教科文组织列入名录(2017年)。", uncertain: "khaen 究竟是中国笙的直接祖先,还是平行发展的结果,尚无定论。", techniques: [{ name: "和弦持续音", how: "数根管同时发声,在旋律之下形成持续的和声。" }, { name: "气息脉动", how: "吸气与吹气交替,使和弦产生节奏性的脉动。" }] },
"t-rung": { sound: "轻盈、空灵、木质的“笃”声,衰减迅速,如水滴或潺潺溪流;快速交织的音型闪烁生辉。", range: "约两到三个八度,视竹管数目而定。", tuning: "竹管通过切削调成五声音阶;现代音乐会用的乐器则调成自然音阶。", acoustics: "鼓槌敲击 → 竹管(作为音条振动)→ 其自身的空气柱。", materials: "按长短排列、穿在绳上的竹管。", making: "由演奏者以干竹按大小分级制作,竹管切削至音高,用藤条排列捆扎。", usage: "挂在架上或绑在柱上,用两支竹槌敲击。", role: "旋律。", players: "巴那(Ba Na)、嘉莱(Gia Rai)等高原民族的男子;妇女和儿童在田间演奏小型的。", skills: "双槌快速交织的旋律。", scenes: "高原村寨节庆、田间、现代乐队。", repertoire: "高原旋律;现代“西原”(Tây Nguyên)音乐会作品。", origin: "越南中部高原诸民族(巴那、嘉莱等)的竹管木琴。", history: "起初是吓鸟的田间乐器,后来成为垂直悬挂或倾斜放置的旋律乐器。", variants: "只有几根管的田间乐器;15至20根或更多管的音乐会用 t'rưng。", today: "仍在使用,在现代民族乐队中占有重要地位。", techniques: [{ name: "敲击竹管", how: "鼓槌敲击悬挂的竹管,发出轻盈空灵的音色。" }, { name: "颤音", how: "快速交替敲击,形成涟漪般的声音。" }] },
"dan-da": { sound: "清澈、明亮、干脆的响亮咔声,衰减短促,如玻璃般却带石质,比金属音条更轻、更硬。", range: "约一到两个八度,视套组而定。", tuning: "每块石板的音高靠打磨削凿设定;出土的套组呈现类似音阶的序列,有时接近五声音阶。", acoustics: "琴槌敲击 → 石板(音条振动)。", materials: "削凿过的长条石板。", making: "史前套组像石器一样从变质岩上打制而成;现代复制品由工匠削凿并调音。", usage: "平放在柔软的支撑物上,用棍或槌敲击。", role: "旋律。", players: "高原族群;今天为乐队乐师。", skills: "带闷击与敞击的旋律性敲击。", scenes: "史前仪式;现代复兴音乐会。", repertoire: "高原旋律;现代复兴音乐会。", origin: "越南中部高原的定音石板琴(石磬),是已知最古老的石磬之一。", finds: "1949年在多乐省(Đắk Lắk)的 Ndut Lieng Krak 发现的十一块石板一套,由乔治·孔多米纳斯(Georges Condominas)研究;此后在庆和省和中部高原又发现许多套,年代可能在公元前2000年至前1000年。", history: "1949年起发现的史前套组(Ndut Lieng Krak)被发现是经过调音的;高原民族保留着石编磬。", today: "在音乐会和博物馆中得到复兴。", uncertain: "出土套组的年代和原初用途存在争议,因为它们是在无法断代的地层之外发现的。", techniques: [{ name: "敲击石板", how: "木槌敲击石板,发出干脆响亮的音色。" }] },
"dan-goong": { sound: "柔和的拨弦叮咚声,似竖琴,略带嗡鸣;将葫芦贴在胸前或移开,可使音色更温暖或更单薄。", range: "约一个半到两个八度。", tuning: "通过移动小琴码,将琴弦调成五声音阶。", acoustics: "手指拨弦 → 小琴码上的金属丝弦 → 竹管,葫芦作为额外的共鸣体。", materials: "竹管、架在小琴码上的金属弦、葫芦共鸣体。", making: "由演奏者以竹管、金属弦(过去为劈开的竹篾或金属丝)和半个葫芦制成。", usage: "竖持,葫芦贴在胸前,双手拨弦。", role: "旋律与歌唱伴奏。", players: "巴那、嘉莱等高原民族的男子。", skills: "双手交织拨弦、用葫芦贴靠身体来调节音色。", scenes: "求偶、私下的歌唱、乡村生活。", repertoire: "求偶歌曲与个人旋律。", origin: "中部高原民族(巴那、嘉莱)的管状齐特琴,弦绕竹管,带葫芦共鸣体。", history: "与从马达加斯加到菲律宾都有的管状齐特琴相关,在高原上由男子演奏。", today: "濒危,但由长者和复兴团体保存。", techniques: [{ name: "拨弦", how: "手指拨动竹管齐特琴的琴弦。" }] },
"k-ni": { sound: "纤细、嗡嗡作响、带刮擦感的弓弦音色,经演奏者的口腔滤成类似元音的声音,仿佛在说话或唱词。", range: "约一个八度或略多。", acoustics: "弓 → 单根弦 → 线 → 含在口中的圆片;口腔作为共鸣体并塑造音色。", materials: "竹制或木制琴杆、一根弦、一根线和葫芦片吹口;一把弓。", making: "由演奏者以竹或木杆、一根弦(过去用藤纤维,现用金属丝或尼龙)、一根线和一小片葫芦或木片制成。", usage: "圆片含在唇间,同时拉弦;口腔作为共鸣体。", role: "旋律,如人声般的独奏。", players: "嘉莱和巴那的男子与青年。", skills: "通过口型塑造元音与如说话般的旋律、滑音。", scenes: "求偶、讲故事、高原生活。", repertoire: "通过乐器“说出”的求偶话语与故事。", meaning: "用来说出不便大声说出口的爱语。", origin: "越南中部高原嘉莱和巴那人的单弦“口弦提琴”。", history: "弦上的线通向含在演奏者口中的圆片,口腔塑造类似元音的声音,使这件乐器能够“说话”。", today: "濒危。", uncertain: "构造细节因村而异,各来源的记述也不一致。", techniques: [{ name: "口腔共鸣", how: "演奏者把线含在口中并塑造元音,使拉出的音色听来如同说话。" }] },
"cong-chieng": { sound: "凸脐的 cồng 发出深沉温暖的嗡鸣轰响,平面的 chiêng 发出较明亮铿锵的响声,交织成密集的、带拍频泛音而闪烁的脉动。", range: "整套跨越两到三个八度,从深沉的低音锣到小而高的锣。", tuning: "每一套通过锤打调成村寨自己的音阶;不同民族和不同套组的调音各异。", acoustics: "槌或拳击打 → 青铜板(凸脐或平面)→ 周围的自由空气。", materials: "青铜或黄铜锣,凸脐的“cồng”和平面的“chiêng”。", making: "多数锣购自低地的京族、老族或高棉族锻匠,再由高原的专门工匠通过锤打重新调音。", usage: "挂在肩上,用包布槌或拳头敲击,常边走边绕圈。", role: "以轮奏(hocket)产生旋律与节奏:每位演奏者发出音型中的一个音。", players: "社群中的男子(某些团体中也有女性),每人在整套中各占一个位置。", skills: "交织的轮奏音型、用手止音。", scenes: "杀水牛祭祀、收获与尝新米节庆、葬礼与村寨仪式。", repertoire: "用于杀水牛祭祀、尝新米、弃墓(pơ thi)及其他村寨仪式的曲目。", meaning: "锣是神圣的,被认为蕴含神灵,也是显示财富和地位的传家宝。", origin: "越南中部高原诸民族的凸脐锣和平面锣组,即被联合国教科文组织列为非物质文化遗产的锣文化。", history: "锣从低地输入,成为神圣的家传珍宝;一排中的每位演奏者各敲一面锣,构成交织的旋律。", variants: "巴那、埃德(Ê Đê)、嘉莱、马(Mạ)、姆农(M'nông)等族的套组,由2面到13面或更多面锣组成。", today: "仍流传;中部高原的锣文化空间被联合国教科文组织列入名录(2005/2008年)。", techniques: [{ name: "敲锣", how: "包布槌或拳头击锣,发出响亮的嗡鸣。" }, { name: "闷击", how: "用手按住锣面,使余音骤停。" }] },
"buffalo-horn": { sound: "响亮、嘶哑、轰鸣的低沉号声,带粗粝的嗡鸣边缘,传遍山谷;熟练的演奏者能使它渐强渐弱。", range: "一两个音。", acoustics: "颤动的嘴唇 → 角上凿的孔 → 锥形的角腔。", materials: "带吹孔的水牛角。", making: "以洗净的水牛角制成,吹孔开在尖端或侧面。", usage: "用颤动的嘴唇吹出一两个音。", role: "信号。", players: "村中的报信者、守夜人、战士和仪式主持者。", skills: "长号声与渐强渐弱。", scenes: "村中召集、节庆、战争信号。", meaning: "号声召集村民并宣告危险,仪式上则宣告节庆开始。", origin: "越南村落和高原民族的水牛角号(tù và)。", history: "自古用来召集村民集会、传递战争信号和标示节庆。", variants: "端吹和侧吹两种形制;沿海则有海螺号。", today: "仍活跃于乡村节庆和仪式。", techniques: [{ name: "长吹", how: "在角的自然音上持续的号声。" }] },
"trong-dong": { sound: "深沉、似锣的金属轰响,伴有响亮的嗡鸣;击鼓面中心音色较暗,近鼓边则较明亮、铿锵。", range: "无固定音高至音高模糊,深沉。", acoustics: "包布槌敲击 → 铸青铜鼓面 → 中空的青铜鼓身(尽管名为鼓,实为体鸣乐器)。", materials: "整体铸造的青铜,带平坦的、装饰过的鼓面。", making: "由东山青铜匠人以失蜡法或分范法整体铸成。", usage: "悬挂或置于地上,用包布槌敲击鼓面。", role: "仪式信号与节奏。", players: "过去为首领和仪式专家;芒族(Mường)和其他民族至今仍使用后期的铜鼓。", skills: "敲击中心的星纹和鼓边的仪式击法。", scenes: "仪式宴飨、祈雨与收获仪式、首领典礼。", meaning: "权力、财富和社群的象征,与祈雨及丰产仪式相关;中央的星纹和鸟纹被解读为太阳的象征。", origin: "越南北部东山文化(约公元前600年至公元200年)的大型青铜鼓,中国南方也有铸造。", finds: "越南北部的玉缕(Ngọc Lũ)、黄河(Hoàng Hạ)和古螺(Cổ Loa)铜鼓,铸于约公元前500年至公元100年;从云南到印度尼西亚都发现有相关的铜鼓。", history: "饰有星纹、鸟、船、舞者和吹 khèn 者,是权力的象征并用于仪式;玉缕铜鼓最为著名。", variants: "黑格尔(Heger)的I至IV型;克伦族蛙饰铜鼓和印度尼西亚的佩珍(Pejeng)型 moko 是后来的亲缘乐器。", today: "古代铜鼓是博物馆的珍宝;后期的铜鼓仍由芒族、倮倮(Lô Lô)和中国南方的一些民族演奏。", techniques: [{ name: "击中心", how: "槌击鼓面中央的星纹,发出响亮的音。" }, { name: "击鼓边", how: "击打近鼓边处,发出更高、更干的声音。" }] },
});
